/* ---- model.js ---- */
/* Rookie Season model: parsing, trait scores, forecasts, player index. No DOM. Loads after data.js. */
"use strict";

const STAT_KEYS = ["W","L","net","off","def","pace","age","tpar","tpm","tpa","tpp","reb","ast","stl","blk","pts","pre","lw","ll"];
const STATS = {};
STATS_RAW.trim().split("\n").forEach(line => {
  const p = line.trim().split(/\s+/), o = {};
  STAT_KEYS.forEach((k, i) => { o[k] = parseFloat(p[i + 1]); });
  STATS[p[0]] = o;
});
const TEAM = {};
TEAMS.forEach(t => { t.st = STATS[t.a]; TEAM[t.a] = t; });
const N = TEAMS.length;
const SEASON_GAMES = 82;
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const ord = n => { const s = ["th","st","nd","rd"], v = n % 100; return n + (s[(v - 20) % 10] || s[v] || s[0]); };
const confName = c => (c === "E" ? "East" : "West");

/* ---------- Forecast ----------
   Each team's chance of winning a remaining game blends two things:
   - what was expected before the season (80% preseason win total, 20% last season's record)
   - how the team has actually played so far (point margin per 100 possessions)
   Early in the season the first counts for more; the second takes over as games pile up. */
const PROJ = {};
TEAMS.forEach(t => {
  const s = t.st, g = s.W + s.L;
  const prior = 0.8 * s.pre / SEASON_GAMES + 0.2 * s.lw / SEASON_GAMES;
  const cur = clamp(0.5 + 0.031 * s.net, 0.12, 0.88);
  const w = g / (g + 25);
  const p = prior * (1 - w) + cur * w;
  PROJ[t.a] = { p, g, wins: s.W + (SEASON_GAMES - g) * p, pct: g ? s.W / g : 0 };
});
["E","W"].forEach(c => {
  const list = TEAMS.filter(t => t.conf === c);
  [...list].sort((a, b) => PROJ[b.a].wins - PROJ[a.a].wins).forEach((t, i) => { PROJ[t.a].seed = i + 1; });
  [...list].sort((a, b) => PROJ[b.a].pct - PROJ[a.a].pct || b.st.net - a.st.net).forEach((t, i) => { PROJ[t.a].now = i + 1; });
});
function zone(seed) {
  if (seed <= 6) return { k: "in", t: "Playoffs", d: "Top six: straight into the playoffs." };
  if (seed <= 10) return { k: "playin", t: "Play-In", d: "Seeds 7 to 10 play extra games for the last two playoff spots." };
  return { k: "out", t: "Misses the playoffs", d: "Bottom five: season ends in April, but a high draft pick is likely." };
}
function forecastLine(t) {
  const p = PROJ[t.a];
  return `${ord(p.seed)} in the ${confName(t.conf)}`;
}

/* ---------- Trait scores ---------- */
function zmap(fn) {
  const v = TEAMS.map(fn), m = v.reduce((a, b) => a + b, 0) / v.length;
  const sd = Math.sqrt(v.reduce((a, b) => a + (b - m) ** 2, 0) / v.length) || 1;
  const o = {};
  TEAMS.forEach((t, i) => { o[t.a] = (v[i] - m) / sd; });
  return o;
}
const Z = {};
["tpm","tpar","tpp","pace","off","pts","def","ast","reb","stl","blk","age"].forEach(k => { Z[k] = zmap(t => t.st[k]); });
const drought = t => (t.titles ? THIS_YEAR - t.last : THIS_YEAR - t.since + 40);
const RAW = {
  threes: t => Z.tpm[t.a] + Z.tpar[t.a] + 0.5 * Z.tpp[t.a],
  pace: t => Z.pace[t.a],
  scoring: t => Z.off[t.a] + 0.5 * Z.pts[t.a],
  defense: t => -Z.def[t.a],
  passing: t => Z.ast[t.a],
  hustle: t => Z.reb[t.a] + Z.stl[t.a] + Z.blk[t.a],
  stars: t => t.star,
  winnow: t => PROJ[t.a].wins,
  young: t => -t.st.age,
  history: t => t.titles + (t.titles ? Math.max(0, 1 - (THIS_YEAR - t.last) / 60) : 0),
  underdog: drought
};
/* SCORES[trait][abbr] = { score: 0-100, rank: 1-30, tied: bool } */
const SCORES = {};
TRAITS.forEach(tr => {
  const vals = TEAMS.map(t => ({ a: t.a, v: RAW[tr.id](t) }));
  const out = {};
  vals.forEach(x => {
    const better = vals.filter(y => y.v > x.v + 1e-9).length;
    const same = vals.filter(y => Math.abs(y.v - x.v) <= 1e-9).length;
    const avgRank = better + (same + 1) / 2;
    out[x.a] = { score: 100 * (1 - (avgRank - 1) / (N - 1)), rank: better + 1, tied: same > 1 };
  });
  SCORES[tr.id] = out;
});
const rankText = (id, t) => { const s = SCORES[id][t.a]; return (s.tied ? "tied " : "") + ord(s.rank) + " of " + N; };

/* A plain-language fact behind each score. */
function fact(id, t) {
  const s = t.st;
  switch (id) {
    case "threes": return `${s.tpm.toFixed(1)} threes made a game, and ${Math.round(s.tpar * 100)}% of their shots are threes`;
    case "pace": return `${s.pace.toFixed(1)} possessions a game`;
    case "scoring": return `${s.pts.toFixed(1)} points a game`;
    case "defense": return `allow ${s.def.toFixed(1)} points per 100 possessions (lower is better)`;
    case "passing": return `${s.ast.toFixed(1)} assists a game`;
    case "hustle": return `${s.reb.toFixed(1)} rebounds, ${s.stl.toFixed(1)} steals and ${s.blk.toFixed(1)} blocks a game`;
    case "stars": return `led by ${t.face[0]}`;
    case "winnow": return `${s.W}–${s.L} so far, on track for about ${Math.round(PROJ[t.a].wins)} wins`;
    case "young": return `average age ${s.age.toFixed(1)}`;
    case "history": return t.titles ? `${t.titles} championship${t.titles > 1 ? "s" : ""}, the last in ${t.last}` : "no championships yet";
    case "underdog": return t.titles ? `last title was ${THIS_YEAR - t.last} years ago (${t.last})` : `no championship since joining the NBA in ${t.since}`;
  }
  return "";
}

/* weights: { traitId: 1 (like) | 2 (love) }. region: "" or a region id. */
const REGION_BONUS = 10;
function match(weights, region) {
  const ids = Object.keys(weights).filter(k => weights[k] > 0 && SCORES[k]);
  const total = ids.reduce((a, k) => a + weights[k], 0);
  return TEAMS.map(t => {
    let score = total ? ids.reduce((a, k) => a + weights[k] * SCORES[k][t.a].score, 0) / total : 0;
    const near = !!region && t.reg === region;
    if (near && total) score = Math.min(100, score + REGION_BONUS);
    const parts = ids.map(k => ({ id: k, w: weights[k], rank: SCORES[k][t.a].rank, score: SCORES[k][t.a].score }))
      .sort((a, b) => b.w * b.score - a.w * a.score);
    return { t, score, near, parts };
  }).sort((a, b) => b.score - a.score || PROJ[b.t.a].wins - PROJ[a.t.a].wins);
}

/* ---------- Players ---------- */
const fold = s => String(s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase().trim();
const PLAYERS = [];
INTL_RAW.trim().split("\n").forEach(line => {
  const i = line.indexOf(":"), c = line.slice(0, i);
  line.slice(i + 1).split(",").forEach(x => { const [n, t] = x.split("@"); PLAYERS.push({ n, c, t }); });
});
US_RAW.split(",").forEach(x => { const [n, t] = x.split("@"); PLAYERS.push({ n, c: "United States", t }); });
EXTRA.forEach(e => PLAYERS.push(Object.assign({}, e)));
PLAYERS.forEach(p => {
  p.k = fold(p.n);
  p.note = p.note || PNOTE[p.n] || "";
  p.roots = ROOTS[p.n] || null;
  p.former = (FORMER[p.n] || "").split("|").filter(Boolean).map(s => { const i = s.indexOf(" "); return { t: s.slice(0, i), y: s.slice(i + 1) }; });
});
const SUBFLAG = { England: "\u{1F3F4}\u{E0067}\u{E0062}\u{E0065}\u{E006E}\u{E0067}\u{E007F}", Scotland: "\u{1F3F4}\u{E0067}\u{E0062}\u{E0073}\u{E0063}\u{E0074}\u{E007F}", Wales: "\u{1F3F4}\u{E0067}\u{E0062}\u{E0077}\u{E006C}\u{E0073}\u{E007F}" };
const flag = c => { if (SUBFLAG[c]) return SUBFLAG[c]; const iso = ISO[c]; return iso ? String.fromCodePoint(...[...iso].map(ch => 0x1F1E6 + ch.charCodeAt(0) - 65)) : ""; };
const COUNTRIES = [...new Set(PLAYERS.map(p => p.c))].filter(c => c !== "United States").sort((a, b) => a.localeCompare(b));
const countryCount = c => PLAYERS.filter(p => p.c === c && p.t).length;
function searchPlayers(q) {
  const k = fold(q);
  if (k.length < 2) return [];
  return PLAYERS.filter(p => p.k.includes(k)).sort((a, b) => (a.k.startsWith(k) ? 0 : 1) - (b.k.startsWith(k) ? 0 : 1) || a.n.localeCompare(b.n)).slice(0, 24);
}
function byCountry(c) {
  return {
    current: PLAYERS.filter(p => p.c === c && p.t),
    elsewhere: PLAYERS.filter(p => p.c === c && !p.t),
    roots: PLAYERS.filter(p => p.roots === c)
  };
}
const usedToPlayFor = a => PLAYERS.filter(p => p.former.some(f => f.t === a));

/* ---------- Leagues and nearby teams ---------- */
const inSeason = (l, month) => l.months.includes(month);
const NEARBY = TEAMS.map(t => ({ name: t.n, place: t.city, league: "NBA", slug: t.s }));
Object.keys(OTHER_TEAMS).forEach(lg => OTHER_TEAMS[lg].split(";").forEach(x => { const [name, place] = x.split("|"); NEARBY.push({ name, place, league: lg }); }));
NEARBY.forEach(x => { x.k = fold(x.name + " " + x.place); });
function searchNearby(q) {
  const k = fold(q);
  if (k.length < 2) return [];
  return NEARBY.filter(x => x.k.includes(k));
}

if (typeof module !== "undefined") module.exports = { STATS, TEAM, PROJ, SCORES, match, fact, zone, PLAYERS, COUNTRIES, byCountry, searchPlayers, searchNearby, NEARBY, usedToPlayFor, rankText, forecastLine };

;
