/* ---- sports.js ---- */
/* Rookie Season: multi-sport layer. Loads after data.js, the league data files and model.js.
   Every sport exposes the same shape so the page code does not care which league it is showing. */
"use strict";

/* ---------- The seven things fans care about, described as personality ---------- */
const GTRAITS = [
  { id: "fireworks", type: "The Thrill-Seeker", label: "Non-stop action",
    blurb: "You want noise, speed and a scoreboard that keeps moving.",
    means: {
      nba: "In basketball, that points to teams that score in bunches and love the three-pointer, a long shot worth 3 points instead of the usual 2.",
      nfl: "In football, that points to high-scoring offences. The offence is the group that has the ball, and a touchdown (carrying or catching it in the end zone) is worth 6 points.",
      nhl: "In hockey, that points to teams that score a lot of goals. Most games end with only five or six goals in total, so a high-scoring team is a treat.",
      mlb: "In baseball, that points to big-hitting teams that pile up runs. A run is one point, scored when a player makes it all the way around the four bases.",
      mls: "In soccer, that points to attacking teams that score plenty of goals. Most games have only two or three, so every goal is an event.",
      nll: "In lacrosse, that points to teams that score the most. Indoor lacrosse games often have 20 or more goals.",
      mlr: "In rugby, that points to teams that score lots of tries, worth five points each, by running the ball over the line."
    } },
  { id: "wall", type: "The Strategist", label: "Smart, stubborn defending",
    blurb: "You enjoy tension, discipline and watching a plan come together.",
    means: {
      nba: "In basketball, that points to strong defensive teams: ones that make every shot difficult and give up few points.",
      nfl: "In football, that points to teams with a fierce defence, the group whose whole job is to stop the other side from scoring.",
      nhl: "In hockey, that points to teams that give up very few goals, usually thanks to a great goalie and disciplined defending.",
      mlb: "In baseball, that points to teams with excellent pitching. The pitcher throws the ball, and a great one makes it almost impossible to hit.",
      mls: "In soccer, that points to teams that give up very few goals: organised defenders and a reliable goalkeeper.",
      nll: "In lacrosse, that points to teams that give up the fewest goals, usually thanks to a great goalie.",
      mlr: "In rugby, that points to teams that give up few points: strong tacklers who rarely let the other side through."
    } },
  { id: "stars", type: "The Star-Gazer", label: "A superstar to follow",
    blurb: "You follow people more than teams. Give you one brilliant player and you are happy.",
    means: { all: "That points to teams with a superstar: a famous player who can win a game almost alone." } },
  { id: "winner", type: "The Winner", label: "Winning right now",
    blurb: "You want a team that is good today. No waiting around.",
    means: { all: "That points to teams on track for the playoffs, the knockout tournament at the end of the season that decides the champion." } },
  { id: "grow", type: "The Talent Scout", label: "Building for the future",
    blurb: "You are patient. You like getting in early and watching something grow.",
    means: { all: "That points to rebuilding teams: young players, not many wins today, and a real chance to be great in a few years. You get to say you were there from the start." } },
  { id: "history", type: "The Traditionalist", label: "History and trophies",
    blurb: "You love a long story, old rivalries and a full trophy case.",
    means: { all: "That points to teams with the most championships and the most famous former players." } },
  { id: "underdog", type: "The Loyal Underdog", label: "Backing the long shot",
    blurb: "You cheer for the ones nobody expects. When they finally win, it will mean more.",
    means: { all: "That points to teams whose fans have waited decades for a championship, or are still waiting for the first one." } }
];
const GT = {};
GTRAITS.forEach(g => { GT[g.id] = g; });
const meansFor = (g, sportId) => g.means[sportId] || g.means.all || "That points to teams that match what you care about most.";

/* ---------- The quiz: seven statements with no sports words. Anyone can answer every one. ---------- */
const QUIZ = [
  { id: "fireworks", q: "I get restless easily. I want something happening all the time." },
  { id: "wall", q: "I love strategy: chess, puzzles, mysteries, watching a clever plan come together." },
  { id: "stars", q: "I follow people more than groups: a favourite singer, actor, author or creator." },
  { id: "winner", q: "I am competitive. I hate losing, even at board games." },
  { id: "grow", q: "I am patient. I like starting something early and watching it grow over years." },
  { id: "history", q: "I love history, tradition and things with a long story behind them." },
  { id: "underdog", q: "I always root for the underdog." }
];
/* "Not me" counts against a trait, so teams built on it drop down the list. */
const LEVELS = [["That's me", 2], ["A little", 1], ["Not me", -1]];
function quizWeights(ans, pick) {
  const w = {};
  ans.forEach((k, i) => { if (k != null && QUIZ[i] && LEVELS[k]) w[QUIZ[i].id] = LEVELS[k][1]; });
  if (pick && w[pick] > 0) w[pick] += 1;
  return w;
}
const topTraits = w => Object.keys(w).filter(k => w[k] > 0).sort((a, b) => w[b] - w[a] || GTRAITS.findIndex(g => g.id === a) - GTRAITS.findIndex(g => g.id === b));

/* ---------- Shared helpers ---------- */
function scoreMap(teams, fn) {
  const vals = teams.map(t => ({ a: t.a, v: fn(t) })), n = teams.length, out = {};
  vals.forEach(x => {
    const better = vals.filter(y => y.v > x.v + 1e-9).length;
    const same = vals.filter(y => Math.abs(y.v - x.v) <= 1e-9).length;
    out[x.a] = { score: 100 * (1 - (better + (same + 1) / 2 - 1) / (n - 1)), rank: better + 1, tied: same > 1 };
  });
  return out;
}
const droughtOf = t => (t.titles ? THIS_YEAR - t.last : THIS_YEAR - t.since + 40);
const historyOf = t => t.titles + (t.titles ? Math.max(0, 1 - (THIS_YEAR - t.last) / 60) : 0);
const pyth = (f, a, e) => Math.pow(f, e) / (Math.pow(f, e) + Math.pow(a, e));

const SPORTS = {};
const SPORT_ORDER = ["nba", "nfl", "nhl", "mlb"];
const SPORT_INFO = {
  nba: { sport: "Basketball", word: "basketball", count: 30,
    feel: "Fast and high-scoring. The easiest sport to pick up: the ball goes in the hoop and the score goes up.",
    rules: "Five players a side. Put the ball through the hoop for 2 points, or 3 from long range. Four 12-minute quarters. Most points wins." },
  nfl: { sport: "Football", word: "football", count: 32,
    feel: "One big game a week. Short bursts of action, huge hits, and the whole country watching.",
    rules: "Eleven players a side. The team with the ball gets four tries, called downs, to move it 10 yards. Reach the end zone for a touchdown, worth 6 points. Kicks add 1 or 3. Four 15-minute quarters." },
  nhl: { sport: "Hockey", word: "hockey", count: 32,
    feel: "The fastest game there is. Goals are rare, so each one brings the house down.",
    rules: "Five skaters and a goalie per side. Shoot the puck into the net for a goal. Three 20-minute periods. If it is tied, they play sudden-death overtime, then a shootout." },
  mlb: { sport: "Baseball", word: "baseball", count: 30,
    feel: "Slow, sunny and social, with sudden drama. There is a game almost every day all summer.",
    rules: "Nine innings. In each one, both teams get a turn to bat. Hit the ball, run around four bases and you score a run. Three outs end your turn. There is no clock." }
};
function finishSport(sp) {
  sp.bySlug = {};
  sp.byName = {};
  sp.teams.forEach(t => { sp.bySlug[t.slug] = t; sp.byName[fold(t.n)] = t; t.sp = sp.id; });
  sp.league = LEAGUES.find(l => l.id === sp.id);
  sp.rankText = (id, t) => { const s = sp.scores[id][t.a]; return (s.tied ? "tied " : "") + ord(s.rank) + " of " + sp.teams.length; };
  /* Each trait pulls a team up or down from the middle (50), in proportion to how much the fan cares. */
  sp.match = weights => {
    const ids = Object.keys(weights).filter(k => weights[k] && sp.scores[k]);
    const total = ids.reduce((a, k) => a + Math.abs(weights[k]), 0);
    return sp.teams.map(t => {
      const score = total ? 50 + ids.reduce((a, k) => a + weights[k] * (sp.scores[k][t.a].score - 50), 0) / total : 0;
      const parts = ids.map(k => ({ id: k, w: weights[k], score: sp.scores[k][t.a].score })).sort((a, b) => b.w * b.score - a.w * a.score);
      return { t, score, parts };
    }).sort((a, b) => (a.t.isNew ? 1 : 0) - (b.t.isNew ? 1 : 0) || b.score - a.score || sp.proj[b.t.a].metric - sp.proj[a.t.a].metric);
  };
  sp.xlabel = id => { const x = sp.xtraits.find(z => z.id === id); return x ? x.t : GT[id] ? GT[id].label : id; };
  sp.fanNote = FAN_DATA[sp.id] ? "Fan numbers: " + FAN_DATA[sp.id].src + "." : "";
  SPORTS[sp.id] = sp;
}

/* ---------- NBA: adapter over the detailed model ---------- */
(function () {
  const sp = Object.assign({
    id: "nba", name: "NBA", teams: TEAMS, snapshot: SNAPSHOT, games: 82,
    venueLabel: "Arena", coachLabel: "Head coach", titleLabel: "Championships", champ: "championship",
    confs: [["E", "Eastern Conference", "East"], ["W", "Western Conference", "West"]],
    recordLabel: "Record right now", metricLabel: "Forecast wins", pillPrefix: "Forecast",
    forecastTitle: "Where every team is headed.",
    forecastIntro: "The NBA is split into two halves, East and West. Each team is ranked inside its half, and that rank is called a seed. Here is where we expect each team to finish when the regular season ends on April 11.",
    legend: [["in", "Seeds 1 to 6 go straight to the playoffs"], ["playin", "Seeds 7 to 10 play extra games for two more spots"], ["out", "Seeds 11 to 15 miss out"]],
    method: ["Teams have played only a small part of their 82 games, so early results can mislead. We blend two things.", "What experts expected before the season: the preseason win totals, with a small nod to last season's record.", "How the team has actually played: its average winning or losing margin, which predicts future results better than its win-loss record does.", "Early on the first counts for more. As games pile up, the second takes over. Injuries and trades can change everything, so treat this as a guide."],
    shop: ["Jerseys and merch (NBA Store)", "https://store.nba.com/"]
  }, SPORT_INFO.nba);
  sp.proj = {};
  sp.scores = {};
  TEAMS.forEach(t => {
    t.slug = t.s;
    const P = PROJ[t.a], z = zone(P.seed);
    sp.proj[t.a] = { metric: P.wins, seed: P.seed, zone: z, cut: P.seed === 6 || P.seed === 10, line: forecastLine(t) };
  });
  const ZW = zmap(t => PROJ[t.a].wins);
  Object.keys(SCORES).forEach(k => { sp.scores[k] = SCORES[k]; });
  sp.xtraits = TRAITS.map(tr => ({ id: tr.id, t: tr.t, d: tr.d }));
  sp.xhint = "three-pointers, defence or star power";
  const raw = {
    fireworks: t => Z.off[t.a] + 0.5 * Z.pts[t.a] + 0.5 * Z.tpm[t.a] + 0.3 * Z.pace[t.a],
    wall: t => -Z.def[t.a] + 0.25 * (Z.stl[t.a] + Z.blk[t.a]),
    stars: RAW.stars, winner: RAW.winnow, grow: t => -Z.age[t.a] - 0.7 * ZW[t.a], history: RAW.history, underdog: RAW.underdog
  };
  GTRAITS.forEach(g => { sp.scores[g.id] = scoreMap(TEAMS, raw[g.id]); });
  sp.fact = (id, t) => {
    const s = t.st;
    switch (id) {
      case "fireworks": return `They score ${s.pts.toFixed(1)} points a game and make ${s.tpm.toFixed(1)} three-pointers`;
      case "wall": return `They give up ${s.def.toFixed(1)} points for every 100 times the other team has the ball. Lower is better`;
      case "stars": return `Their star is ${t.face[0]}`;
      case "winner": return `They are ${s.W}–${s.L} so far and on track for about ${Math.round(PROJ[t.a].wins)} wins out of 82`;
      case "grow": return `Their players average ${s.age.toFixed(1)} years old, and the team is ${PROJ[t.a].seed > 10 ? "still building: on track for about " + Math.round(PROJ[t.a].wins) + " wins" : "already competitive"}`;
      case "history": return t.titles ? `They have ${t.titles} championship${t.titles > 1 ? "s" : ""}, the last in ${t.last}` : "They have no championships yet";
      case "underdog": return t.titles ? (THIS_YEAR - t.last < 1 ? `They are the reigning champions, from ${t.last}` : `Their last title was ${THIS_YEAR - t.last} year${THIS_YEAR - t.last === 1 ? "" : "s"} ago, in ${t.last}`) : `They have never won a championship since joining the league in ${t.since}`;
    }
    return fact(id, t);
  };
  sp.record = t => `${t.st.W}–${t.st.L}`;
  sp.metricText = t => String(Math.round(PROJ[t.a].wins));
  sp.outlook = t => { const P = PROJ[t.a]; return { big: ord(P.seed), text: `in the ${confName(t.conf)}, with about ${Math.round(P.wins)} wins out of 82. Right now they sit ${ord(P.now)}.` }; };
  sp.confOf = t => `${confName(t.conf)}ern Conference · ${t.div} Division`;
  sp.links = t => { const b = `https://www.nba.com/${t.s}`; return [["Official team site", b + "/"], ["Schedule", b + "/schedule"], ["Team news", b + "/news"], ["Tickets", b + "/tickets"]]; };
  finishSport(sp);
})();

/* ---------- NFL, NHL, MLB: built from compact data files ---------- */
/* Team row: [abbr, site, name, nick, city, conf, div, region, venue, coach, colour1, colour2,
              titles, lastTitleYear or firstSeason, star 1-5, young 1-3, face, faceBlurb, legends, rivals, story, titleNote] */
function mkTeams(rows) {
  return rows.map(r => {
    const t = { a: r[0], site: r[1], n: r[2], nick: r[3], city: r[4], conf: r[5], div: r[6], reg: r[7], arena: r[8], coach: r[9], c: [r[10], r[11]],
      titles: r[12], star: r[14], young: r[15], face: [r[16], r[17]], legends: r[18].split(";"), rivals: r[19], story: r[20], tn: r[21] || "", prev: r[22] || "" };
    if (t.titles) t.last = r[13]; else t.since = r[13];
    t.slug = fold(t.nick).replace(/[^a-z0-9]+/g, "-");
    return t;
  });
}
function parseStats(raw, keys) {
  const o = {};
  raw.trim().split("\n").forEach(l => { const p = l.trim().split(/\s+/), s = {}; keys.forEach((k, i) => { s[k] = parseFloat(p[i + 1]); }); o[p[0]] = s; });
  return o;
}
/* perDiv teams qualify from each division, then `wild` more from the rest of the conference. */
function assignSeeds(sp, perDiv, wild, byFormat) {
  sp.confs.forEach(cf => {
    const list = sp.teams.filter(t => t.conf === cf[0]), m = t => sp.proj[t.a].metric;
    let auto = [];
    [...new Set(list.map(t => t.div))].forEach(d => { auto = auto.concat(list.filter(t => t.div === d).sort((a, b) => m(b) - m(a)).slice(0, perDiv)); });
    auto.sort((a, b) => m(b) - m(a));
    const rest = list.filter(t => !auto.includes(t)).sort((a, b) => m(b) - m(a));
    const wilds = rest.slice(0, wild);
    const order = byFormat ? auto.concat(rest) : [...list].sort((a, b) => m(b) - m(a));
    order.forEach((t, i) => {
      const P = sp.proj[t.a];
      P.seed = i + 1;
      P.kind = auto.includes(t) ? "div" : wilds.includes(t) ? "wild" : "out";
      P.zone = sp.zones[P.kind];
      P.cut = byFormat && i + 1 === auto.length + wild;
      P.line = sp.lineOf(t, P);
    });
  });
}
function buildSport(cfg, D) {
  const sp = Object.assign({ teams: mkTeams(D.teams), proj: {}, scores: {}, snapshot: D.snapshot }, SPORT_INFO[cfg.id], cfg);
  const stats = parseStats(D.stats, cfg.keys);
  sp.teams.forEach(t => {
    t.st = stats[t.a];
    if (!t.st) throw new Error(cfg.id + ": no stats for " + t.a);
    t.g = cfg.gp(t.st); t.pf = cfg.pf(t.st) / t.g; t.pa = cfg.pa(t.st) / t.g;
    sp.proj[t.a] = { metric: cfg.metric(t) };
  });
  assignSeeds(sp, cfg.perDiv, cfg.wild, cfg.byFormat);
  const zOf = fn => { const v = sp.teams.map(fn), m = v.reduce((a, b) => a + b, 0) / v.length, sd = Math.sqrt(v.reduce((a, b) => a + (b - m) ** 2, 0) / v.length) || 1, o = {}; sp.teams.forEach((t, i) => { o[t.a] = (v[i] - m) / sd; }); return o; };
  const ZY = zOf(t => t.young), ZM = zOf(t => sp.proj[t.a].metric);
  const raw = { fireworks: t => t.pf, wall: t => -t.pa, stars: t => t.star, winner: t => (cfg.winner ? cfg.winner(t) : sp.proj[t.a].metric), grow: t => ZY[t.a] - 0.7 * ZM[t.a], history: historyOf, underdog: droughtOf };
  sp.xtraits = [
    { id: "fireworks", t: cfg.xoff[0], d: cfg.xoff[1] }, { id: "wall", t: cfg.xdef[0], d: cfg.xdef[1] },
    { id: "stars", t: "Star power", d: "A superstar worth the price of a ticket." },
    { id: "winner", t: "Winning right now", d: "A real shot at the playoffs this season." },
    { id: "grow", t: "Young and rebuilding", d: "A young core that should peak in a few years." },
    { id: "history", t: "History and titles", d: "Banners, legends and decades of stories." },
    { id: "underdog", t: "Long-suffering underdog", d: "A fan base that has waited a very long time." }
  ];
  GTRAITS.forEach(g => { sp.scores[g.id] = scoreMap(sp.teams, raw[g.id]); });
  const ch = cfg.champ;
  sp.fact = (id, t) => {
    switch (id) {
      case "fireworks": return `They ${cfg.tense === "past" ? "scored" : "score"} ${t.pf.toFixed(1)} ${cfg.unit} a game`;
      case "wall": return `They ${cfg.tense === "past" ? "gave" : "give"} up just ${t.pa.toFixed(1)} ${cfg.unit} a game`.replace("just ", sp.scores.wall[t.a].score >= 50 ? "just " : "");
      case "stars": return `Their star is ${t.face[0]}`;
      case "winner": return cfg.winnerFact(t, sp.proj[t.a]);
      case "grow": return ["They lean on experienced veterans", "They mix young players with veterans", "They are built around a young core"][t.young - 1] + (sp.proj[t.a].zone.k === "out" ? ", and they are still building toward the playoffs" : ", and they are already competitive");
      case "history": return t.titles ? `They have won the ${ch} ${t.titles === 1 ? "once" : t.titles + " times"}, most recently in ${t.last}` : `They have never won the ${ch}`;
      case "underdog": return t.titles ? (THIS_YEAR - t.last < 1 ? `They won the ${ch} this year, in ${t.last}` : `They last won the ${ch} ${THIS_YEAR - t.last} year${THIS_YEAR - t.last === 1 ? "" : "s"} ago, in ${t.last}`) : `They are still waiting for a first ${ch} win`;
    }
    return "";
  };
  sp.metricText = t => String(Math.round(sp.proj[t.a].metric));
  sp.confOf = t => `${sp.confs.find(c => c[0] === t.conf)[1]} · ${t.div}`;
  finishSport(sp);
  return sp;
}

