/* Playoff teams set by hand where the format is not simply "top N" (for example, the CFL crossover). */
function setPlayoffs(sp, list, inText, outText) {
  sp.teams.forEach(t => { const P = sp.proj[t.a]; const isIn = list.includes(t.a);
    P.kind = isIn ? "div" : "out"; P.zone = isIn ? { k: "in", t: inText[0], d: inText[1] } : { k: "out", t: outText[0], d: outText[1] }; P.cut = false; });
}
/* New teams with no games yet: neutral numbers, so the picker neither favours nor punishes them. */
function markNew(sp, list, note) {
  sp.teams.forEach(t => { if (!list.includes(t.a)) return; t.isNew = true;
    sp.proj[t.a].zone = { k: "out", t: "New team", d: note }; sp.proj[t.a].kind = "out";
    Object.keys(sp.scores).forEach(k => { if (k !== "history" && k !== "underdog") sp.scores[k][t.a] = Object.assign({}, sp.scores[k][t.a], { score: 50 }); }); });
  Object.keys(sp.scores).forEach(k => { const m = sp.scores[k]; const vals = sp.teams.map(t => m[t.a].score);
    sp.teams.forEach(t => { const v = m[t.a].score; m[t.a].rank = 1 + vals.filter(x => x > v + 1e-9).length; m[t.a].tied = vals.filter(x => Math.abs(x - v) < 1e-9).length > 1; }); });
  const old = sp.teams.filter(t => !t.isNew).sort((a, b) => sp.proj[a.a].seed - sp.proj[b.a].seed);
  old.forEach((t, i) => { sp.proj[t.a].seed = i + 1; sp.proj[t.a].line = sp.lineOf(t, sp.proj[t.a]); });
  sp.teams.forEach(t => { if (t.isNew) sp.proj[t.a].line = sp.lineOf(t, sp.proj[t.a]); });
  const fact = sp.fact; sp.fact = (id, t) => t.isNew && id !== "history" && id !== "underdog" ? "A new team: no games played yet" : fact(id, t);
  const rec = sp.record; sp.record = t => t.isNew ? "New" : rec(t);
  const ol = sp.outlook; sp.outlook = (t, P) => t.isNew ? { big: "New", text: note } : ol(t, P);
}

