/* Volleyball: attack and defence are not tracked, so those traits are neutral for every team. */
function volleyFix(sp) {
  sp.noColours = true;
  /* Attack and defence are not tracked for volleyball, so those traits are left out of matching and of the team pages. */
  ["fireworks", "wall", "balance"].forEach(k => { delete sp.scores[k]; });
  if (sp.xtraits) sp.xtraits = sp.xtraits.filter(x => sp.scores[x.id]);
  sp.marginNote = t => t.isNew ? "A new team: no matches played yet" : `They won ${t.st.W} and lost ${t.st.L} matches in 2026`;
}

