      xoff: def.xoffT || K.xoff, xdef: def.xdefT || K.xdef, keys: K.keys, unit: def.unit || K.unit, gp: K.gp, pf: K.pf, pa: K.pa, metric: def.keepOrder ? (t => (def.metric || K.metric)(t) - rows.findIndex(r => r[0] === t.a) / 1e6) : (def.metric || K.metric), perDiv: n, tense: def.done ? "past" : "present",
      recordLabel: def.done ? def.season + " record" : "Record so far", pillPrefix: def.done ? def.season + " finish" : "Now", forecastTitle: def.done ? "How the season finished." : "The table right now.",
      venueLabel: def.venueLabel || K.venue, titleLabel: def.titleLabel || "League titles", champ: def.champ || "league title", metricLabel: K.keys.includes("PTS") ? "Points" : "Win %", coachLabel: def.coachLabel || "Head coach",
      confs: def.confs || [[def.id.toUpperCase(), def.confName || def.country || def.full, def.name]],
      zones: { div: { k: "mid", t: "", d: "" }, wild: { k: "mid", t: "", d: "" }, out: { k: "mid", t: "", d: "" } },
      lineOf: (t, P) => def.confs ? `${ord(P.seed)} in the ${def.confs.find(c => c[0] === t.conf)[2]}` : `${ord(P.seed)} of ${n}`,
      winnerFact: t => "PTS" in t.st ? `They ${def.done ? "finished with" : "have"} ${t.st.PTS} points from ${t.st.GP} games` : `They ${def.done ? "went" : "are"} ${K.record(t)}${def.done ? "" : " so far"}`,
      record: K.record,
      outlook: (t, P) => ({ big: ord(P.seed), text: `of ${def.confs ? sp.teams.filter(x => x.conf === t.conf).length : n} in the ${def.confs ? def.confs.find(c => c[0] === t.conf)[1] : def.name}${def.done ? " in " + def.season : ` after ${t.st.GP} games`}${"PTS" in t.st ? `, with ${t.st.PTS} points` : ""}. ${K.recordNote}`.trim() }),
