/* Link soccer squad players (data-socp.js) to the quick-league clubs, so team pages show the full squad. Runs after bench.js. */
function quickLinkPlayers() {
  if (typeof ALLP === "undefined") return;
  const k = s => fold(s).replace(/\b(fc|afc|cf|sc|ac|as|ssc|rc|ogc|vfb|vfl|tsg|sv|bv|1|04|05|07|09|de|cd|ud|rcd)\b/g, "").replace(/[^a-z]/g, "");
  const ALIAS = { internazionale: "intermilan", inter: "intermilan", milan: "acmilan", roma: "asroma", athleticclub: "athleticbilbao", koln: "cologne", fccologne: "cologne", rennes: "staderennais" };
  const norm = s => { const x = k(s); return ALIAS[x] || x; };
  QL.forEach(def => {
    const sp = SPORTS[def.id]; if (!sp || def.kind !== "soccer") return;
    const by = new Map(sp.teams.map(t => [norm(t.n), t]));
    let hit = 0;
    ALLP.forEach(p => { if (p.sp !== "soc" || p.lg !== def.id) return;
      const c = norm(p.club || ""); let t = by.get(c);
      if (!t) for (const [kk, tt] of by) if (kk.length > 3 && (kk.includes(c) || c.includes(kk))) { t = tt; break; }
      if (t) { p.t = t; p.rpos = p.pos; hit++; } });
    if (hit && typeof ROSTER_ORDER !== "undefined") ROSTER_ORDER[def.id] = [["Goalkeeper", "Goalkeepers"], ["Defender", "Defenders"], ["Midfielder", "Midfielders"], ["Forward", "Forwards"]];
    if (hit && typeof ROSTER_SRC !== "undefined") ROSTER_SRC[def.id] = "each club's Wikipedia page";
  });
}

