/* Rookie Season extras: team colours, wiki and social links, minor leagues, European soccer, other sports.
   Loaded after sports.js and before app.js. View functions here use helpers from app.js (esc, state, colors, teamHref). */

/* ---------- Team colours ---------- */
const COLOR_FAMS = [["red", "Red", "#D62839"], ["maroon", "Maroon", "#7B1E3A"], ["orange", "Orange", "#F47A20"], ["gold", "Gold or yellow", "#F2C230"],
  ["green", "Green", "#1E8A4C"], ["teal", "Teal or aqua", "#12A5A8"], ["blue", "Blue", "#2F6FDE"], ["navy", "Navy", "#1B2D5E"], ["purple", "Purple", "#6B3FA0"],
  ["pink", "Pink", "#F4A6C6"], ["brown", "Brown", "#5A3A22"], ["black", "Black", "#111111"], ["silver", "Silver or grey", "#B5BBC4"]];
const FAM_NAME = {}; COLOR_FAMS.forEach(f => { FAM_NAME[f[0]] = f[1].split(" or ")[0].toLowerCase(); });
function hslOf(hex) {
  const n = parseInt(hex.slice(1), 16), r = (n >> 16) / 255, g = ((n >> 8) & 255) / 255, b = (n & 255) / 255;
  const mx = Math.max(r, g, b), mn = Math.min(r, g, b), l = (mx + mn) / 2, d = mx - mn;
  let h = 0, s = 0;
  if (d) { s = d / (1 - Math.abs(2 * l - 1)); h = mx === r ? ((g - b) / d) % 6 : mx === g ? (b - r) / d + 2 : (r - g) / d + 4; h = (h * 60 + 360) % 360; }
  return [h, s, l];
}
function colorFam(hex) {
  const [h, s, l] = hslOf(hex);
  if (s < 0.2) return l > 0.9 ? "silver" : l > 0.4 ? "silver" : "black";
  if (l > 0.93) return "silver";
  if ((h >= 300 || h < 10) && l > 0.68) return "pink";
  if (h >= 15 && h < 50 && l < 0.3) return "brown";
  if (l < 0.1) return h >= 200 && h < 260 && l > 0.05 && s > 0.8 ? "navy" : "black";
  if (h < 12 || h >= 335) return l < 0.33 ? "maroon" : "red";
  if (h < 32) return "orange";
  if (h < 65) return "gold";
  if (h < 165) return "green";
  if (h < 192) return l < 0.2 ? "green" : "teal";
  if (h < 244) return l < 0.24 ? "navy" : "blue";
  if (h < 300) return "purple";
  return l < 0.33 ? "maroon" : "red";
}
const COLOR_FIX = { mlb: { COL: ["purple", "silver"] } };
function teamFams(sp, t) {
  if (!t._fams) t._fams = (COLOR_FIX[sp.id] && COLOR_FIX[sp.id][t.a]) || [colorFam(t.c[0]), colorFam(t.c[1])];
  return t._fams;
}
function colorWords(sp, t) { const f = teamFams(sp, t); return f[0] === f[1] ? FAM_NAME[f[0]] : FAM_NAME[f[0]] + " and " + FAM_NAME[f[1]]; }

/* ---------- Wikipedia and social links ---------- */
const WIKI_FIX = { "Texas Rangers": "Texas_Rangers_(baseball)", "Athletics": "Athletics_(baseball)", "LA Clippers": "Los_Angeles_Clippers", "Montréal Canadiens": "Montreal_Canadiens", "Chicago Hounds": "Chicago_Hounds_(rugby_union)", "Anthem RC": "Anthem_Rugby_Carolina", "CF Montréal": "CF_Montréal" };
function wikiUrl(name) { return "https://en.wikipedia.org/wiki/" + (WIKI_FIX[name] || encodeURIComponent(name.replace(/ /g, "_"))); }
const SOCIAL_MAP = {};
Object.keys(SOCIAL).forEach(lg => { SOCIAL_MAP[lg] = {}; Object.keys(SOCIAL[lg]).forEach(net => { SOCIAL_MAP[lg][net] = {}; SOCIAL[lg][net].split(";").forEach(p => { const i = p.indexOf(":"); SOCIAL_MAP[lg][net][p.slice(0, i)] = p.slice(i + 1); }); }); });
function socialLinks(sp, t) {
  const m = SOCIAL_MAP[sp.id] || {}, out = [];
  if (m.x && m.x[t.a]) out.push(["X (Twitter)", "https://x.com/" + m.x[t.a]]);
  if (m.ig && m.ig[t.a]) out.push(["Instagram", "https://www.instagram.com/" + m.ig[t.a] + "/"]);
  return out;
}

/* ---------- Minor leagues ---------- */
const MINOR_LEAGUES = [
  { id: "il", sport: "mlb", name: "International League", level: "Triple-A" }, { id: "pcl", sport: "mlb", name: "Pacific Coast League", level: "Triple-A" },
  { id: "el", sport: "mlb", name: "Eastern League", level: "Double-A" }, { id: "sl", sport: "mlb", name: "Southern League", level: "Double-A" }, { id: "tl", sport: "mlb", name: "Texas League", level: "Double-A" },
  { id: "mwl", sport: "mlb", name: "Midwest League", level: "High-A" }, { id: "sal", sport: "mlb", name: "South Atlantic League", level: "High-A" }, { id: "nwl", sport: "mlb", name: "Northwest League", level: "High-A" },
  { id: "cal", sport: "mlb", name: "California League", level: "Single-A" }, { id: "car", sport: "mlb", name: "Carolina League", level: "Single-A" }, { id: "fsl", sport: "mlb", name: "Florida State League", level: "Single-A" },
  { id: "ahl", sport: "nhl", name: "American Hockey League (AHL)", level: "AHL" }, { id: "echl", sport: "nhl", name: "ECHL", level: "ECHL" },
  { id: "whl", sport: "nhl", name: "Western Hockey League (WHL)", level: "Junior", free: true }, { id: "ohl", sport: "nhl", name: "Ontario Hockey League (OHL)", level: "Junior", free: true }, { id: "qmjhl", sport: "nhl", name: "Quebec Maritimes Junior Hockey League (QMJHL)", level: "Junior", free: true },
  { id: "gl", sport: "nba", name: "NBA G League", level: "G League" },
  { id: "ufl", sport: "nfl", name: "United Football League (UFL)", level: "Spring league", free: true }
];
const MINORS = [];
MINOR_LEAGUES.forEach(L => {
  L.teams = (MINOR_RAW[L.id] || "").split("\n").filter(Boolean).map(line => {
    const p = line.split("|"), cs = p[1].split(", "), sp = SPORTS[L.sport];
    const parent = p[2] && sp ? sp.byName[fold(p[2])] || sp.teams.find(t => fold(t.n) === fold(p[2])) || null : null;
    const m = { n: p[0], place: p[1], st: cs[cs.length - 1], parentName: p[2] || "", parent, lg: L };
    MINORS.push(m); return m;
  });
});
const MINOR_WIKI = { "San Diego Clippers": "San_Diego_Clippers_(NBA_G_League)", "Maine Mariners": "Maine_Mariners_(ECHL)", "Norfolk Admirals": "Norfolk_Admirals_(ECHL)", "Colorado Stampede": "United_Football_League_(2024)", "Rhode Island Breakers": "United_Football_League_(2024)" };
function minorWiki(m) { return "https://en.wikipedia.org/wiki/" + (MINOR_WIKI[m.n] || encodeURIComponent(m.n.replace(/ /g, "_"))); }
function farmOf(sp, t) { return MINORS.filter(m => m.parent === t); }
const MINOR_INFO = {
  mlb: { word: "Baseball", top: "MLB",
    intro: "Almost every baseball player spends years in the minor leagues before reaching the majors. Each of the 30 MLB teams has four farm teams, one at each level, which makes 120 teams. The MLB team pays the players and decides who moves up. The minor-league team itself is a local business that sells the tickets and the hot dogs.",
    rungs: [["MLB", "30 teams", "The major leagues. The top."],
      ["Triple-A", "30 teams, 2 leagues", "One step away. A mix of nearly ready prospects and experienced players waiting for a call."],
      ["Double-A", "30 teams, 3 leagues", "Where the best young prospects are really tested. Some stars jump straight from here to MLB."],
      ["High-A", "30 teams, 3 leagues", "Usually a player's second or third year as a professional."],
      ["Single-A", "30 teams, 3 leagues", "The first full season. Many players are teenagers or were just drafted."],
      ["Rookie ball", "No fixed cities", "Beginner leagues played at the MLB teams' training bases in Arizona, Florida and the Dominican Republic."]],
    moves: [["Called up", "Promoted to the next level, or to MLB itself."], ["Sent down or optioned", "Moved back down a level to play every day. It is not always a punishment."], ["Rehab assignment", "An injured MLB star plays a few minor-league games to get ready. It is a cheap way to see a famous player up close."], ["The draft", "Every July, MLB teams pick amateur players over 20 rounds. Nearly all of them start in the minors."]],
    also: "Outside this system there are independent leagues with no MLB parent (the Atlantic League, American Association, Frontier League and Pioneer League), summer leagues for college players, and the Arizona Fall League, where top prospects play in October and November.",
    why: "Tickets are cheap, the team names are deliberately playful (Trash Pandas, Sod Poodles, Jumbo Shrimp), and you get to watch future stars from a few rows away." },
  nhl: { word: "Hockey", top: "NHL",
    intro: "Hockey has a two-step ladder under the NHL. Every NHL team has its own AHL team, and most also have an ECHL partner one level lower. Before any of that, most players come through junior hockey or college, and NHL teams draft them at 18 and wait while they develop.",
    rungs: [["NHL", "32 teams", "The top league."],
      ["AHL", "32 teams", "One step below. Every NHL team has exactly one AHL team, and most NHL players spent time here. The champion wins the Calder Cup."],
      ["ECHL", "30 teams", "Two steps below. Most teams are partnered with an NHL club. The champion wins the Kelly Cup."],
      ["Junior hockey", "61 teams, 3 leagues", "The WHL, OHL and QMJHL, for players aged 16 to 20. NHL teams do not own these clubs. They draft players out of them. The three champions and a host team play for the Memorial Cup."],
      ["College and Europe", "", "The other routes in: U.S. college hockey, and pro leagues in Sweden, Finland, Czechia and elsewhere."]],
    moves: [["Called up", "Promoted from the AHL to the NHL, often to cover an injury."], ["Sent down or reassigned", "Moved to the AHL to get more ice time."], ["The draft", "Each June, NHL teams pick players who are 18. The team keeps the right to sign that player for years while he develops in junior, college or Europe."], ["Entry-level contract", "A drafted player's first NHL deal, which fixes his pay for up to three years."]],
    also: "Junior teams fill arenas across Canada, and in many small towns they are the biggest show there is.",
    why: "AHL and junior games are fast, cheap and close to the ice, and the best players will be in the NHL within a couple of years." },
  nba: { word: "Basketball", top: "NBA",
    intro: "Basketball has one minor league: the NBA G League. All 30 NBA teams have their own G League team, usually in a smaller city nearby. Most NBA players arrive from college basketball or from leagues overseas.",
    rungs: [["NBA", "30 teams", "The top league."],
      ["G League", "31 teams", "One team for each NBA club, plus the independent Mexico City Capitanes. The season runs November to April."],
      ["College basketball", "350+ schools", "Where most American players spend one to four years. Its national tournament in March, known as March Madness, is one of the biggest events in U.S. sports."],
      ["Overseas", "", "Many players, including several of the NBA's biggest stars, grew up in European and other pro leagues."]],
    moves: [["Two-way contract", "A deal that lets a player split the season between the NBA team and its G League team. Each NBA team can have three."], ["Assignment", "An NBA team sends a young player to its G League team for more playing time."], ["Call-up", "A G League player signs with an NBA team, often on a 10-day contract to start."], ["The draft", "Every June, NBA teams pick 60 players over two rounds."]],
    also: "The NBA Summer League in July, mostly in Las Vegas, is where draft picks play their first games in an NBA uniform.",
    why: "G League tickets are cheap, arenas are small, and players are fighting for an NBA job in every game." },
  nfl: { word: "Football", top: "NFL",
    intro: "Football is the odd one out. The NFL has no farm teams at all. College football does the job instead: players spend at least three years there before an NFL team can draft them, and college games draw crowds as big as NFL games.",
    rungs: [["NFL", "32 teams", "The top league. Each team has 53 players."],
      ["Practice squad", "16 extra players per team", "Players who train with an NFL team all week but do not play on Sunday unless they are promoted."],
      ["College football", "130+ top-division schools", "The real development league. Games are on Saturdays. The best teams enter a 12-team playoff for the national championship in January."],
      ["Spring leagues", "8 teams", "The United Football League (UFL) plays from spring into early summer. It is independent, and players use it to earn another chance at the NFL."]],
    moves: [["The draft", "Every April, NFL teams take turns picking college players over seven rounds. The worst teams pick first."], ["Undrafted free agent", "A player nobody drafted who signs with a team anyway. Some become stars."], ["Elevated", "A practice-squad player moved up to play in that week's game."], ["Waived or cut", "Released by the team. Rosters shrink from 90 players to 53 before the season."]],
    also: "The Canadian Football League (CFL) is not a minor league. It is a separate professional league with its own rules, a bigger field and nine teams.",
    why: "If you like football, a college team is often the easiest second team to adopt. Many people pick the big school in their state." }
};

function rungsHTML(info) {
  return `<ol class="ladder">${info.rungs.map((r, i) => `<li class="${i === 0 ? "top" : ""}"><div><b>${esc(r[0])}</b>${r[1] ? `<span>${esc(r[1])}</span>` : ""}</div><p>${esc(r[2])}</p></li>`).join("")}</ol>`;
}
function minorTable(list, showParent) {
  return `<div class="tablebox"><table><thead><tr><th>Team</th><th>Plays in</th>${showParent ? "<th>Feeds</th>" : ""}</tr></thead><tbody>${list.map(m =>
    `<tr><td><a class="plain" href="${minorWiki(m)}" target="_blank" rel="noopener"><b>${esc(m.n)}</b></a></td><td>${esc(m.place)}</td>${showParent ? `<td>${m.parent ? `<a href="${teamHref(m.parent)}">${esc(m.parent.n)}</a>` : esc(m.parentName || "Independent")}</td>` : ""}</tr>`).join("")}</tbody></table></div>`;
}
function farmHTML(sp, t) {
  const info = MINOR_INFO[sp.id], farm = farmOf(sp, t);
  if (!info) return "";
  if (!farm.length) return `<section class="panel"><h2>Where the players come from</h2><p>${esc(info.intro)}</p><p><a class="more" href="#minors-${sp.id}">How ${esc(info.word.toLowerCase())} players reach the ${esc(info.top)}</a></p></section>`;
  return `<section class="panel"><h2>Farm teams</h2>
    <p class="hint">The ${esc(t.nick)} own or partner with these lower-level teams. Young players work their way up through them, nearest to the ${esc(info.top)} first.</p>
    <ul class="farm">${farm.map(m => `<li><span class="tag">${esc(m.lg.level)}</span><a class="plain" href="${minorWiki(m)}" target="_blank" rel="noopener"><b>${esc(m.n)}</b></a><span class="muted">${esc(m.place)}</span></li>`).join("")}</ul>
    <p><a class="more" href="#minors-${sp.id}">How the ${esc(info.word.toLowerCase())} ladder works</a></p></section>`;
}
function vMinors(id) {
  const order = ["mlb", "nhl", "nba", "nfl"].filter(k => SPORTS[k]);
  if (!MINOR_INFO[id]) id = state.ml && MINOR_INFO[state.ml] ? state.ml : "mlb";
  const sp = SPORTS[id], info = MINOR_INFO[id], leagues = MINOR_LEAGUES.filter(L => L.sport === id);
  const tabs = order.map(k => `<a class="chip" href="#minors-${k}" ${k === id ? 'aria-current="true"' : ""}>${esc(MINOR_INFO[k].word)}</a>`).join("");
  const pick = state.mp && sp.teams.find(t => t.a === state.mp) || null, farm = pick ? farmOf(sp, pick) : [];
  const here = state.loc ? MINORS.filter(m => m.lg.sport === id && m.st === state.loc) : [];
  const hasFarm = leagues.some(L => !L.free);
  let lastLevel = "";
  const lists = leagues.map(L => {
    const head = L.level !== lastLevel ? `<h3 class="lvl">${esc(L.level)}</h3>` : ""; lastLevel = L.level;
    return `${head}<details><summary>${esc(L.name)} <span class="muted">· ${L.teams.length} teams</span></summary>${minorTable(L.teams, !L.free)}</details>`;
  }).join("");
  return `
  <a class="back" href="#leagues">← More leagues</a>
  <section class="hero">
    <p class="eyebrow">Minor leagues · ${esc(info.word)}</p>
    <h1>The road to ${id === "mlb" ? "" : "the "}${esc(info.top)}.</h1>
    <p class="lede">${esc(info.intro)}</p>
    <div class="chips">${tabs}</div>
  </section>
  <div class="cols two">
    <section class="panel"><h2>The ladder</h2><p class="hint">Top of the list is the top of the sport. Players climb upward.</p>${rungsHTML(info)}</section>
    <section class="panel"><h2>Words you will hear</h2><dl class="gl">${info.moves.map(m => `<div><dt>${esc(m[0])}</dt><dd>${esc(m[1])}</dd></div>`).join("")}</dl>
      <h3>Why watch</h3><p>${esc(info.why)}</p><h3>Also good to know</h3><p>${esc(info.also)}</p></section>
  </div>
  ${hasFarm ? `<section class="panel"><h2>Find a team's farm system</h2>
    <div class="field"><label for="mp">Pick an ${esc(info.top)} team</label><select id="mp"><option value="">Choose a team</option>${sp.teams.slice().sort((a, b) => a.n.localeCompare(b.n)).map(t => `<option value="${t.a}" ${state.mp === t.a ? "selected" : ""}>${esc(t.n)}</option>`).join("")}</select></div>
    ${pick ? (farm.length ? `<ul class="farm">${farm.map(m => `<li><span class="tag">${esc(m.lg.level)}</span><a class="plain" href="${minorWiki(m)}" target="_blank" rel="noopener"><b>${esc(m.n)}</b></a><span class="muted">${esc(m.place)}</span></li>`).join("")}</ul><p><a class="more" href="${teamHref(pick)}">Meet the ${esc(pick.nick)}</a></p>` : `<p class="empty">No farm teams listed for the ${esc(pick.nick)}.</p>`) : ""}
  </section>` : ""}
  <section class="panel"><h2>Teams near you</h2>
    ${locControl()}
    ${state.loc ? (here.length ? minorTable(here, true) : `<p class="empty">No ${esc(info.word.toLowerCase())} teams at these levels play in ${esc(state.loc)}.</p>`) : `<p class="hint">Pick where you live to see the lower-level ${esc(info.word.toLowerCase())} teams there. Minor-league games are often the cheapest live sport around.</p>`}
  </section>
  <section class="stack"><div><h2>Every team, level by level</h2><p class="hint">Tap a league to open its list. ${leagues.reduce((n, L) => n + L.teams.length, 0)} teams in all. Lists from ${esc(MINOR_SNAPSHOT)}.</p></div>${lists}</section>`;
}

/* ---------- Pick by colours ---------- */
function lookHTML(sp) {
  const chosen = state.col || [];
  const chips = COLOR_FAMS.map(f => `<button type="button" class="chip swchip" id="col-${f[0]}" data-act="col" data-id="${f[0]}" aria-pressed="${chosen.includes(f[0])}"><i style="background:${f[2]}"></i>${esc(f[1])}</button>`).join("");
  const res = state.done ? sp.match(quizWeights(state.ans, state.pick)) : null, pct = {};
  if (res) res.forEach(m => { pct[m.t.a] = m.score; });
  let teams = sp.teams.map(t => { const f = teamFams(sp, t); return { t, hits: chosen.filter(c => f.includes(c)).length, main: chosen.includes(f[0]) ? 1 : 0, hue: hslOf(t.c[0])[0] }; });
  if (chosen.length) teams = teams.filter(x => x.hits).sort((a, b) => b.hits - a.hits || b.main - a.main || (pct[b.t.a] || 0) - (pct[a.t.a] || 0) || a.t.n.localeCompare(b.t.n));
  else teams.sort((a, b) => a.hue - b.hue || a.t.n.localeCompare(b.t.n));
  const cards = teams.map(x => { const t = x.t, P = sp.proj[t.a];
    return `<a class="swatch" href="${teamHref(t)}" style="${colors(t)}"><span class="kit"><i></i><i></i></span><b class="swname">${badge(t)}<span>${esc(t.n)}</span></b><span class="muted">${esc(colorWords(sp, t))}</span>
      <span class="swmeta">${res ? `<span>${Math.round(pct[t.a])}% quiz match</span>` : ""}<span class="pill ${P.zone.k}">${esc(P.zone.t)}</span></span></a>`; }).join("");
  return `<section class="panel">
    <h2>Pick by colours</h2>
    <p class="hint">Plenty of fans chose their team because they loved the look. Tap the colours you like${chosen.length ? "" : ", or just browse the wall"}.</p>
    <div class="chips">${chips}</div>
    <p class="muted">${chosen.length ? `${teams.length} ${teams.length === 1 ? "team wears" : "teams wear"} ${chosen.map(c => FAM_NAME[c]).join(" or ")}.` : `All ${sp.teams.length} teams, sorted by colour.`} We show each team's two main colours. Logos and jersey designs belong to the teams, so each team page links to where you can see them.</p>
    <div class="qnav">${changeBtn}</div>
  </section>
  <div class="swgrid" id="swatches">${cards || `<p class="empty">No ${esc(sp.name)} team wears that. Try another colour.</p>`}</div>`;
}

/* ---------- Promotion and relegation, around the world (v39) ----------
   Which leagues on the site send their bottom clubs down, and which are closed. Ids link to each league's page. */
const PROREL = [
  ["Europe", "Every men's league here, and most of the women's leagues", ["eng", "esp", "ita", "ger", "fra", "por", "ned", "bel", "tur", "cze", "sco"]],
  ["South America", "Every league here. Several decide relegation over two or three seasons, not one", ["bra", "bra2", "arg", "chi", "col", "uru", "par", "ecu", "per", "bol", "ven"]],
  ["Asia", "Japan, Saudi Arabia and China", ["j1", "ksa", "csl", "cl1"]],
  ["Africa", "Every league here", ["egy", "mar", "alg", "rsa", "nga"]],
  ["Other sports", "It is not only soccer: Spain's basketball league and France's rugby union league do it too", ["acb", "top14"]]];
const CLOSED = [
  ["North America", "MLS, the NWSL and the other leagues here have no relegation. Liga MX in Mexico stopped it in 2020 and confirmed in 2026 that it will not return for now", ["mls", "nwsl", "usls", "ligamx"]],
  ["Elsewhere", "Australia's A-League, England's Premiership Rugby, the KHL, the EuroLeague and the big cricket leagues are closed too", ["aleague", "prem", "khl", "euroleague", "ipl"]]];
function proRelHTML() {
  const link = id => SPORTS[id] ? `<a class="chip" href="#${id}">${esc(SPORTS[id].name)}</a>` : "";
  const rows = list => list.map(([where, what, ids]) => `<div class="prrow"><div><b>${esc(where)}</b><p class="muted">${esc(what)}.</p></div><div class="chips">${ids.map(link).join("")}</div></div>`).join("");
  return `<section class="panel" id="prorel">
    <h2>Promotion and relegation around the world</h2>
    <p class="hint">This is not just a European idea. Almost every country's soccer league works this way, with a second division (and often many more) underneath. North America is the main exception: its leagues are closed, so a team stays in the league however badly it does.</p>
    <h3>Leagues here that use it</h3><div class="prlist">${rows(PROREL)}</div>
    <h3>Closed leagues</h3><div class="prlist">${rows(CLOSED)}</div>
    <p class="muted">On most league tables on this site, coloured bands show which places go up or go down this season.</p>
  </section>`;
}
/* ---------- European soccer ---------- */
const ZONE = { cl: ["Champions League", "in"], clq: ["Champions League qualifying", "in"], el: ["Europa League", "mid"], ecl: ["Conference League", "lite"], po: ["Relegation play-off", "gone"], rel: ["Relegated", "gone"] };
EURO_LEAGUES.forEach(L => {
  const z = {};
  L.zones.split(";").forEach(p => { const [k, r] = p.split(":"), ab = r.split("-").map(Number); for (let i = ab[0]; i <= (ab[1] || ab[0]); i++) z[i] = k; });
  L.table = L.rows.split("\n").map((line, i) => { const p = line.split("|"); return { pos: i + 1, n: p[0], city: p[1], gp: +p[2], pts: +p[3], zone: z[i + 1] || "" }; });
});
const CUP_OF = {};
EURO_CUPS.forEach(c => { c.groups = c.clubs.split(";").map(g => { const i = g.indexOf(":"); const clubs = g.slice(i + 1).split(","); clubs.forEach(n => { CUP_OF[n] = c; }); return [g.slice(0, i), clubs]; }); c.count = c.groups.reduce((n, g) => n + g[1].length, 0); });
function leagueHTML(L) {
  const rows = L.table.map((r, i) => { const nxt = L.table[i + 1], cut = nxt && nxt.zone !== r.zone, cup = CUP_OF[r.n];
    return `<tr class="${cut ? "cut" : ""}"><td class="seed num">${r.pos}</td><td><b>${esc(r.n)}</b><div class="muted sub">${esc(r.city)}${cup ? " · in this season's " + esc(cup.name) : ""}</div></td><td class="n">${r.gp}</td><td class="n"><b>${r.pts}</b></td><td>${r.zone ? `<span class="pill ${ZONE[r.zone][1]}">${ZONE[r.zone][0]}</span>` : `<span class="muted">Stays up</span>`}</td></tr>`; }).join("");
  return `<div class="stack" id="league-out">
    <div class="lhead"><div><p class="eyebrow">${esc(L.country)} · ranked ${ord(L.rank)} in Europe</p><h3>${esc(L.name)}</h3></div><div class="links"><a href="${esc(L.url)}" target="_blank" rel="noopener">Official site</a></div></div>
    <p class="lead">${esc(L.blurb)}</p>
    <dl class="facts"><div><dt>Clubs</dt><dd>${L.table.length}</dd></div><div><dt>Reigning champion</dt><dd>${esc(L.champ)}</dd></div><div><dt>Drop down to</dt><dd>${esc(cap(L.second))}</dd></div><div><dt>Table from</dt><dd>${esc(L.asof)}</dd></div></dl>
    <div><h4>Clubs to know</h4><ul class="know">${L.know.map(k => `<li><b>${esc(k[0])}.</b> ${esc(k[1])}</li>`).join("")}</ul></div>
    <div class="tablebox"><table><thead><tr><th></th><th>Club</th><th class="n">Played</th><th class="n">Points</th><th>If the season ended today</th></tr></thead><tbody>${rows}</tbody></table></div>
    <p class="muted">${esc(L.note)} It is early in the season, so expect this to change a lot.</p></div>`;
}
function vSoccer() {
  const cur = EURO_LEAGUES.find(L => L.id === state.lg) || EURO_LEAGUES[0];
  const chips = EURO_LEAGUES.map(L => `<button type="button" class="chip" id="lg-${L.id}" data-act="lg" data-id="${L.id}" aria-pressed="${L === cur}">${esc(L.country)}</button>`).join("");
  const cups = EURO_CUPS.map(c => `<article class="lcard"><div class="tags"><span class="tag">${esc(c.level)}</span></div><h3>${esc(c.name)}</h3><p>${esc(c.what)}</p>
    <dl><div><dt>Current holder</dt><dd>${esc(c.holder)}${c.holderNote ? " (" + esc(c.holderNote) + ")" : ""}</dd></div><div><dt>This season's final</dt><dd>${esc(c.final)}</dd></div></dl>
    <details><summary>The ${c.count} clubs in it this season</summary><div>${c.groups.map(g => `<p><b>${esc(g[0])}:</b> ${esc(g[1].join(", "))}</p>`).join("")}</div></details>
    <div class="links"><a href="${esc(c.url)}" target="_blank" rel="noopener">Official site</a></div></article>`).join("");
  return `
  <a class="back" href="#leagues">← More leagues</a>
  <section class="hero">
    <p class="eyebrow">Soccer explained · latest tables</p>
    <h1>The world's game, explained.</h1>
    <p class="lede">Most soccer leagues outside North America work very differently from the big four. Start with the three ideas below, see which leagues use promotion and relegation, then pick a country in Europe, where the strongest leagues are.</p>
  </section>
  <section class="panel">
    <h2>Three things that are different</h2>
    <div class="three">
      <div><span class="bignum">1</span><h3>No playoffs</h3><p>Every club plays every other club twice, home and away. A win is three points, a draw is one. Whoever has the most points at the end is champion. That is it.</p></div>
      <div><span class="bignum">2</span><h3>Relegation and promotion</h3><p>In most countries, the bottom two to four clubs are relegated, which means sent down to the division below. The best clubs from that division are promoted to replace them. No team is safe, and small clubs can climb all the way up.</p></div>
      <div><span class="bignum">3</span><h3>Three trophies at once</h3><p>While the league runs, clubs also play their country's knockout cup and, if they finished high enough last season, a Europe-wide competition in midweek.</p></div>
    </div>
  </section>
  ${proRelHTML()}
  <section class="panel">
    <h2>Where does a team end up in Europe?</h2>
    <p class="hint">A club's final league position decides its next season. From top to bottom of a typical table:</p>
    <ol class="ladder">
      <li class="top"><div><b>Top places</b><span><span class="pill in">Champions League</span></span></div><p>Next season they play Europe's best clubs for the biggest prize in club soccer. Four clubs qualify from the strongest leagues, one or two from smaller ones.</p></li>
      <li><div><b>Just below</b><span><span class="pill mid">Europa League</span></span></div><p>Europe's second competition. The winner of the country's knockout cup usually gets in here too.</p></li>
      <li><div><b>Next</b><span><span class="pill lite">Conference League</span></span></div><p>The third competition, a chance for mid-table clubs to win a European trophy.</p></li>
      <li><div><b>The middle</b><span>Stays up</span></div><p>Safe. They play in the same league next year.</p></li>
      <li><div><b>Bottom places</b><span><span class="pill gone">Relegated</span></span></div><p>Down to the second division, with far less TV money. Fighting to avoid this is often more dramatic than the title race.</p></li>
    </ol>
  </section>
  <section class="panel">
    <h2>The top 10 leagues</h2>
    <p class="hint">Ranked by how their clubs have done in Europe over the last five seasons. Pick a country to see its table and where each club would end up.</p>
    <div class="chips">${chips}</div>
    ${leagueHTML(cur)}
  </section>
  <section class="stack">
    <div><h2>The three European competitions</h2><p class="hint">Played on weeknights from September to early summer, alongside the home leagues. Each has 36 clubs in one big table. A club plays a handful of different opponents, the top eight go straight to the last 16, the next sixteen play off for the other places, and the rest are out. After that it is knockout rounds to a one-game final.</p></div>
    <div class="lgrid">${cups}</div>
  </section>
  <section class="panel">
    <h2>How this ties to North America</h2>
    <p><b>Major League Soccer (MLS)</b> works like the other American leagues: fixed teams, no relegation, and playoffs ending in the MLS Cup. The level is below Europe's top leagues, but the games are local, cheap and growing fast. Many fans follow an MLS team in person and a European club on TV.</p>
    <p><b>The World Cup</b> is for countries, not clubs, every four years. Canada, Mexico and the United States hosted in 2026, and Spain won it. The next one is in 2030.</p>
    <p><b>Picking a club.</b> There is no wrong way. People choose the club of a favourite player, the club their family supports, the colours they like, or an underdog whose story grabbed them.</p>
    <p><a class="more" href="#leagues">MLS and other North American leagues</a></p>
  </section>`;
}

