/* ---------- The leading statistics site for each sport ---------- */
const REF_SITES = { nba: ["Basketball-Reference", "https://www.basketball-reference.com/"], nfl: ["Pro-Football-Reference", "https://www.pro-football-reference.com/"], nhl: ["Hockey-Reference", "https://www.hockey-reference.com/"], mlb: ["Baseball-Reference", "https://www.baseball-reference.com/"] };

/* ---------- Positions, explained ---------- */
const POS_INFO = {
  nba: { order: ["PG", "SG", "SF", "PF", "C"],
    PG: ["Point guard", "Runs the offence. Usually the best passer and ball-handler, and often the smallest player on the floor."],
    SG: ["Shooting guard", "A scorer who plays away from the basket. Usually one of the team's best long-range shooters."],
    SF: ["Small forward", "The all-rounder: big enough to play near the basket and quick enough to play away from it."],
    PF: ["Power forward", "A strong player who works near the basket and collects missed shots, called rebounds. Many now shoot from distance too."],
    C: ["Centre", "Usually the tallest player. Protects the basket on defence and scores close to it on offence."] },
  nfl: { order: ["QB", "RB", "WR", "TE", "OL", "DL", "LB", "CB", "S", "K", "P", "RET", "LS"],
    map: { LT: "OL", C: "OL", LG: "OL", RG: "OL", RT: "OL", LDE: "DL", RDE: "DL", LDT: "DL", RDT: "DL", NT: "DL", DE: "DL", DT: "DL", WLB: "LB", MLB: "LB", SLB: "LB", LILB: "LB", RILB: "LB", LCB: "CB", RCB: "CB", NB: "CB", SS: "S", FS: "S", KR: "RET", PR: "RET", LG: "OL", RG: "OL", RT: "OL", FB: "RB" },
    QB: ["Quarterback", "The leader of the offence. He takes the ball to start each play, then throws it, hands it to a runner or runs himself."],
    RB: ["Running back", "Takes the ball from the quarterback and runs with it. Also catches short passes."],
    WR: ["Wide receiver", "Lines up near the sideline, runs downfield and catches passes."],
    TE: ["Tight end", "Part blocker, part receiver. Bigger than a wide receiver, and lines up beside the offensive line."],
    OL: ["Offensive line", "The big players who protect the quarterback and clear a path for runners. We list the left tackle, who guards the quarterback's blind side, and the centre, who starts each play by snapping the ball back."],
    DL: ["Defensive line", "The players at the front of the defence. They stop runs and chase the quarterback. Tackling him behind the line is called a sack."],
    LB: ["Linebacker", "Lines up behind the defensive line. Tackles runners, covers receivers and sometimes rushes the quarterback."],
    CB: ["Cornerback", "Covers the wide receivers and tries to stop them catching passes."],
    S: ["Safety", "The last line of defence, positioned deep to stop long passes and big runs."],
    K: ["Kicker", "Kicks field goals, worth 3 points, and the extra point after a touchdown."],
    P: ["Punter", "Kicks the ball far down the field on fourth down, when the offence gives up trying, so the other team starts further from the end zone."],
    RET: ["Kick and punt returner", "Catches the other team's kicks and punts and runs them back. Usually one of the fastest players on the team."],
    LS: ["Long snapper", "A specialist who snaps the ball back to the punter or the kicker's holder. He rarely does anything else, but a bad snap can lose a game."] },
  mlb: { order: ["SP", "CL", "C", "1B", "2B", "3B", "SS", "LF", "CF", "RF", "DH"],
    SP: ["Starting pitcher", "Throws the ball to the batter from the start of the game, usually for five to seven innings. A team rotates through five starters, one per game."],
    CL: ["Closer", "A relief pitcher who comes in at the very end to protect a narrow lead."],
    C: ["Catcher", "Crouches behind home plate, catches every pitch and helps the pitcher decide what to throw."],
    "1B": ["First baseman", "Fields the area around first base and catches throws from the other infielders to get runners out."],
    "2B": ["Second baseman", "Covers the infield between first and second base. Needs quick hands and feet."],
    "3B": ["Third baseman", "Guards third base, where the hardest-hit balls arrive. Needs fast reactions and a strong arm."],
    SS: ["Shortstop", "Plays between second and third base. Usually the team's best fielder."],
    LF: ["Left fielder", "Covers the left side of the outfield, the big grass area beyond the bases."],
    CF: ["Centre fielder", "Covers the middle of the outfield. Usually the fastest player on the team."],
    RF: ["Right fielder", "Covers the right side of the outfield. Usually has the strongest throwing arm."],
    DH: ["Designated hitter", "Bats in place of the pitcher and does not play in the field."] },
  nhl: { order: ["C", "LW", "RW", "F", "D", "G"],
    C: ["Centre", "Plays the middle of the ice, takes the face-offs that restart play, and helps at both ends."],
    LW: ["Left wing", "A forward who plays along the left side. Wingers are often the main goal-scorers."],
    RW: ["Right wing", "A forward who plays along the right side. Wingers are often the main goal-scorers."],
    F: ["Forward", "An attacking player who can play centre or wing."],
    D: ["Defenseman", "Plays in front of his own goalie, breaks up attacks and starts the team moving the other way. Two are on the ice at a time."],
    G: ["Goalie", "Stops the puck from going in the net. The most important single player in most games."] }
};
const LINEUP_NOTE = { nba: "The eight players with the most playing time this season. Source: Basketball-Reference.", nfl: "The first-choice player at every position on ESPN's depth chart, Nov 16, 2026. Injured players are left off, so check the injury list below.", mlb: "The regular starters, the five-man pitching rotation and the closer from 2026. Source: Baseball-Reference.", nhl: "Source: Hockey-Reference, ESPN and Wikipedia." };
const LU = {};
Object.keys(LINEUPS).forEach(id => {
  LU[id] = {};
  LINEUPS[id].split("|").forEach(row => { const i = row.indexOf("="); LU[id][row.slice(0, i)] = row.slice(i + 1).split(";").map(x => { const p = x.split(":"), star = p[1].endsWith("*"); return { pos: p[0], n: star ? p[1].slice(0, -1) : p[1], star, c: p[2] || "" }; }); });
});
if (typeof ROSTERS !== "undefined") ROSTERS.nhl.split(";").forEach(block => { const i = block.indexOf(":"); LU.nhl[block.slice(0, i)] = block.slice(i + 1).split("~").map(r => { const p = r.split("|"); return { pos: p[1], n: p[0], star: false, c: p[4] }; }); });
/* NHL: DailyFaceoff line combinations replace the roster lists. Each player keeps the country we already had. */
if (typeof NHL_LINES !== "undefined") Object.keys(NHL_LINES).forEach(ab => {
  const L = NHL_LINES[ab], old = LU.nhl[ab] || [], cOf = n => (old.find(p => p.n === n) || {}).c || "", out = [];
  ["F1", "F2", "F3", "F4"].forEach((k, i) => (L[k] || []).forEach((n, j) => out.push({ pos: L[k].length === 3 ? ["LW", "C", "RW"][j] : "F", n, star: i === 0, c: cOf(n), line: i + 1 })));
  ["D1", "D2", "D3"].forEach((k, i) => (L[k] || []).forEach(n => out.push({ pos: "D", n, star: i === 0, c: cOf(n), line: i + 1 })));
  (L.G || []).forEach((n, i) => out.push({ pos: "G", n, star: i === 0, c: cOf(n), line: i + 1 }));
  LU.nhl[ab] = out;
});
function lineupOf(sp, t) { return (LU[sp.id] && LU[sp.id][t.a]) || []; }
function lineupHTML(sp, t) {
  const list = lineupOf(sp, t), info = POS_INFO[sp.id];
  if (!list.length || !info) return "";
  const groups = {};
  list.forEach(p => { const k = (info.map && info.map[p.pos]) || p.pos; (groups[k] = groups[k] || []).push(p); });
  const rows = info.order.filter(k => groups[k] || !(sp.id === "nhl" && k === "F")).map(k => `<details class="pos"><summary><b>${esc(info[k][0])}</b><span class="who">${groups[k] ? groups[k].map(p => esc(p.n) + (p.gone ? '<i title="Not on any roster right now">no team now</i>' : sp.id === "nhl" && p.line ? `<i>${p.pos === "G" ? (p.line === 1 ? "starter" : "backup") : p.pos === "D" ? "pair " + p.line : "line " + p.line}</i>` : p.star ? '<i title="Usual starter">starter</i>' : "")).join(", ") : '<span class="muted">None listed</span>'}</span><span class="ask">What is this?</span></summary><p>${esc(info[k][1])}</p></details>`).join("");
  const nhl = sp.id === "nhl" && typeof NHL_LINES !== "undefined" && NHL_LINES[t.a];
  const linesTable = nhl ? `<h3>Line combinations</h3><p class="hint">Hockey shifts last under a minute, so teams rotate four forward lines, three defence pairs and a goalie. The first line plays the most.</p>
    <div class="tablebox"><table><thead><tr><th>Forwards</th><th>Left wing</th><th>Centre</th><th>Right wing</th></tr></thead><tbody>${["F1", "F2", "F3", "F4"].map((k, i) => { const L = nhl[k] || []; return `<tr><td><b>Line ${i + 1}</b></td>${(L.length === 3 ? L : [L[0] || "", L[1] || "", L[2] || ""]).map(n => `<td>${esc(n || "Not listed")}</td>`).join("")}</tr>`; }).join("")}</tbody></table></div>
    <div class="tablebox"><table><thead><tr><th>Defence</th><th>Left</th><th>Right</th></tr></thead><tbody>${["D1", "D2", "D3"].map((k, i) => `<tr><td><b>Pair ${i + 1}</b></td>${(nhl[k] || []).map(n => `<td>${esc(n)}</td>`).join("")}</tr>`).join("")}<tr><td><b>Goalies</b></td><td>${esc((nhl.G || [])[0] || "")} <span class="muted">(starter)</span></td><td>${esc((nhl.G || [])[1] || "")} <span class="muted">(backup)</span></td></tr></tbody></table></div>` : "";
  const note = nhl ? "Line combinations from DailyFaceoff, Nov 16, 2026. Lines change often, sometimes game to game." : esc(LINEUP_NOTE[sp.id]) + " Collected on Nov 15, 2026.";
  return `<section class="panel"><h2>The line-up</h2><p class="hint">Who plays where. Select any position to see what it means.</p><div class="poslist">${rows}</div>${linesTable}<p class="muted">${note}</p></section>${injuriesHTML(sp, t)}`;
}
/* Line-up players join the players page, so they can be found by name or by team. */
(function () {
  const byKey = new Map(); ALLP.forEach(p => { const k = p.sp + ":" + p.k; if (!byKey.has(k)) byKey.set(k, p); });
  Object.keys(LU).forEach(id => { const sp = SPORTS[id], info = POS_INFO[id]; if (!sp) return;
    Object.keys(LU[id]).forEach(ab => { const t = sp.teams.find(x => x.a === ab); if (!t) return;
      LU[id][ab].forEach(p => { const k = fold(p.n), posName = info[(info.map && info.map[p.pos]) || p.pos];
        const old = byKey.get(id + ":" + k);
        if (old) { if (!old.pos && posName) old.pos = posName[0]; if (old.t !== t) old.t = t; return; }
        const np = { n: p.n, k, sp: id, t, town: "", place: "", c: p.c || "", note: "", pos: posName ? posName[0] : "", roots: null, former: [] }; byKey.set(id + ":" + k, np); ALLP.push(np); }); }); });
})();

/* ---------- More glossary terms, found by searching ---------- */
const GLOSS_MORE = [
  ["Salary cap", "A limit on how much a team may spend on player wages in a season. It stops the richest teams from buying every star."],
  ["Cap space", "The room a team has left under the salary cap to sign or trade for players."],
  ["Luxury tax", "A penalty a team pays to the league when its wage bill goes over a set line. Used in the NBA and MLB."],
  ["First apron", "An NBA spending line a little above the luxury tax. Teams over it lose some ways of adding players."],
  ["Second apron", "A higher NBA spending line with harsher limits: teams over it can barely make trades or sign extra players."],
  ["Free agent", "A player whose contract has ended and who is free to sign with any team."],
  ["Restricted free agent", "A player who can negotiate with other teams, but whose current team may keep him by matching the offer."],
  ["Trade", "A swap between teams. Players, draft picks and sometimes money change hands."],
  ["Trade deadline", "The last day of a season on which teams may trade. Contenders add players and struggling teams sell them."],
  ["Draft pick", "The right to choose a new young player in the yearly draft. Picks are traded like currency."],
  ["Conditional pick", "A draft pick whose value depends on something that has not happened yet, such as how often the traded player plays."],
  ["Protected pick", "A traded draft pick that the original team keeps if it lands very high, for example in the top five."],
  ["Compensatory pick", "An extra draft pick the NFL gives a team that lost good players to free agency."],
  ["Draft lottery", "A draw among the worst teams to decide who picks first. It stops teams from losing on purpose to guarantee the top pick."],
  ["Tanking", "Losing on purpose, or at least not trying hard to win, to get a better draft pick."],
  ["Rebuild", "When a team trades its older players for young ones and draft picks, accepting a few bad seasons to be good later."],
  ["Rookie contract", "A new player's first deal, with pay largely fixed by where he was drafted."],
  ["Max contract", "The largest deal league rules allow a team to offer a player."],
  ["Two-way contract", "An NBA deal that lets a player split his time between the main team and its G League team."],
  ["Franchise tag", "An NFL rule that lets a team keep one player for a further year at a high set salary instead of letting him leave."],
  ["Waivers", "When a team releases a player, the other teams get a short window to claim him and his contract."],
  ["Buyout", "A team and a player agree to end a contract early, usually so he can join a contender."],
  ["No-trade clause", "A contract term that lets a player refuse to be traded."],
  ["Sign-and-trade", "A team re-signs its own free agent only to trade him straight away, so it gets something back."],
  ["Dead money", "Wages that still count against a team's salary cap for a player who is no longer on the team."],
  ["Injured reserve", "A list for players with long-term injuries. It frees their place on the active roster."],
  ["Call-up", "Promoting a player from a minor-league team to the main team."],
  ["Designated for assignment", "A baseball move that takes a player off the roster while the team decides whether to trade, release or demote him."],
  ["Qualifying offer", "A one-year contract offer a team makes to keep some rights over a player who is about to become a free agent."],
  ["Wild card", "A playoff place for a strong team that did not win its division."],
  ["Bye", "A week off. In the playoffs, a bye means a top team skips the first round."],
  ["Power play", "In hockey, a spell when one team has more players on the ice because an opponent is serving a penalty."],
  ["Overtime", "Extra play to settle a game that is tied at the end of normal time."],
  ["Home-field advantage", "Playing more games in your own stadium. The better seed gets it in the playoffs."],
  ["General manager", "The executive who builds the team: he signs, trades and drafts the players. Often shortened to GM."],
  ["Farm system", "The minor-league teams a club uses to develop its young players."]
];

/* ---------- Sports that are huge elsewhere ---------- */
const WORLD_SPORTS = [
  ["Australian rules", "Australia", "Eighteen players a side on a huge oval field. Players kick, run and punch the ball, and score by kicking it between tall posts. The AFL Grand Final in Melbourne draws about 100,000 people."],
  ["Gaelic football and hurling", "Ireland", "Ireland's two national games, played by amateurs who represent their home county. Hurling, played with a stick and a small ball, is among the fastest field sports in the world."],
  ["Sumo", "Japan and Mongolia", "Two wrestlers try to force each other out of a ring or onto the ground. Bouts last seconds. Six 15-day tournaments are held each year, and many recent champions have come from Mongolia."],
  ["Kabaddi", "India and South Asia", "A raider crosses into the other team's half, tags defenders and tries to get back before being tackled, all in one breath. India's Pro Kabaddi League draws enormous TV audiences."],
  ["Badminton", "China, Indonesia, India, Malaysia, Denmark", "The fastest racket sport: a shuttlecock can leave the racket at more than 400 km/h. Hugely popular across Asia."],
  ["Table tennis", "China and East Asia", "China's national sport and an Olympic event since 1988. Rallies are won and lost in fractions of a second."],
  ["Handball", "Germany, France, Scandinavia", "Seven a side on an indoor court. Players pass by hand and throw at a goal. Fast, physical and high-scoring."],
  ["Volleyball", "Brazil, Italy, Poland, Japan", "Six a side over a high net, indoors, or two a side on sand. One of the most-played sports in the world."],
  ["Field hockey", "India, Pakistan, the Netherlands, Australia", "Eleven a side with sticks and a hard ball on artificial turf. India and Pakistan dominated it for decades."],
  ["Netball", "Australia, New Zealand, England, Jamaica", "A relative of basketball with no dribbling and fixed zones for each player. Mostly played by women."],
  ["Road cycling", "France, Italy, Belgium, Spain", "Teams race for three weeks around a country. The Tour de France each July is the biggest annual sporting event by live spectators."],
  ["Darts and snooker", "Britain and Ireland", "Two precision games that fill arenas and draw big TV audiences every winter."]
];
function worldSportsHTML() {
  return `<section class="stack" id="elsewhere"><div><h2>Huge elsewhere</h2><p class="hint">Sports that get little attention in North America but are followed by many millions of people.</p></div>
    <div class="wgrid">${WORLD_SPORTS.map(s => `<article class="panel"><div class="tags"><span class="tag">${esc(s[1])}</span></div><h3>${esc(s[0])}</h3><p class="muted">${esc(s[2])}</p></article>`).join("")}</div></section>`;
}

/* ---------- Birthplaces for players who had none ---------- */
(function () {
  if (typeof TOWNS === "undefined") return;
  const canada = new Set(CA_PLACES);
  Object.keys(TOWNS).forEach(id => { const by = {}; TOWNS[id].split(";").forEach(r => { const p = r.split("|"); by[fold(p[0])] = p; });
    ALLP.forEach(p => { if (p.sp !== id || p.town) return; const hit = by[p.k]; if (!hit) return; p.town = hit[1]; p.place = hit[2]; if (!p.c) p.c = canada.has(hit[2]) ? "Canada" : US_PLACES.includes(hit[2]) ? "United States" : hit[2]; }); });
})();

/* ---------- Team facts strip: always a full row, no empty cells ---------- */
const LAST_LABEL = { nba: "Last season", nhl: "Last season (2025–26)", nfl: "Last season (2025)", mlb: "2026 finish" };
function factsHTML(sp, t, titleLine) {
  const last = t.prev || (typeof LAST_SEASON !== "undefined" && LAST_SEASON[sp.id] && LAST_SEASON[sp.id][t.a]) || "";
  const items = [["Home city", esc(t.city)], [sp.venueLabel, esc(t.arena)], (t.coach && t.coach !== "Not listed" ? [sp.coachLabel, esc(t.coach)] : ["League", esc(sp.full || sp.name)]), [sp.recordLabel, `<span class="num">${esc(sp.record(t))}</span>`], [sp.titleLabel, titleLine]];
  if (last) items.push([LAST_LABEL[sp.id] || "Last season", esc(last)]);
  else items.push(["Plays in", esc(sp.confOf(t))]);
  return `<dl class="facts six">${items.map(x => `<div><dt>${esc(x[0])}</dt><dd>${x[1]}</dd></div>`).join("")}</dl>`;
}
function histHTML(sp, t) {
  const h = typeof HISTORY !== "undefined" && HISTORY[sp.id] && HISTORY[sp.id][t.a];
  return h ? `<h3>History</h3><p>${esc(h[0])}</p><h3>Fun fact</h3><p>${esc(h[1])}</p>` : "";
}

