/* ---------- Injury list ---------- */
const INJ_WORD = { "LTIR": "Long-term injured reserve: out for a long stretch, and his pay can come off the salary cap. He does not count on the active roster.", "Injured reserve": "On the injured list for at least a set number of games. He does not count on the active roster.", "Out": "Will not play in the next game.", "Day-to-day": "A minor problem. Decided game by game.", "Doubtful": "Unlikely to play this week." };
function injuriesHTML(sp, t) {
  if (typeof INJURIES === "undefined") return "";
  if (!INJURIES[sp.id]) return sp.id === "mlb" ? `<section class="panel"><h2>Injury list</h2><p class="muted">Baseball is in its off-season, so there is no current injury list. It returns in spring training.</p></section>` : "";
  const list = INJURIES[sp.id].map(l => l.split("|")).filter(r => r[0] === t.n || r[0].endsWith(" " + t.nick) || r[0] === t.nick);
  const pillK = st => st === "LTIR" ? "in" : st === "Injured reserve" || st === "Out" ? "playin" : "out";
  return `<section class="panel"><h2>Injury list</h2><p class="hint">Players who are hurt right now. Injured players often drop off the line-up above, so a star can be missing from it.</p>
    ${list.length ? `<div class="tablebox"><table><thead><tr><th>Player</th><th>Position</th><th>Status</th><th>Injury</th></tr></thead><tbody>${list.map(r => `<tr><td><b>${esc(r[1])}</b></td><td>${esc(r[2])}</td><td><span class="pill ${pillK(r[3])}" title="${esc(INJ_WORD[r[3]] || "")}">${esc(r[3])}</span></td><td>${esc(r[4] || "Not given")}</td></tr>`).join("")}</tbody></table></div>` : `<p>No injuries listed.</p>`}
    <details class="pos"><summary><b>What do these mean?</b><span class="who"></span><span class="ask">Explain</span></summary><p>${Object.keys(INJ_WORD).map(k => `<b>${esc(k)}.</b> ${esc(INJ_WORD[k])}`).join(" ")}</p></details>
    <p class="muted">From ESPN's injury report, ${INJ_DATE}. ${sp.id === "nfl" ? "Only players with a named injury are shown." : ""}</p></section>`;
}

