  EuroLeague: "#FB923C", "Premiership Rugby": "#A3E635", "Top 14": "#2DD4BF", "The Hundred": "#F0ABFC", CBA: "#F87171", "Liga ACB": "#FDBA74", CEBL: "#FCA5A5", "Big Bash League": "#FDE047",
  NPB: "#EF4444", KBO: "#3B82F6", IPL: "#F59E0B",
