  svg.querySelectorAll(".vdot").forEach(c => c.setAttribute("r", (+c.dataset.r * grow * v.w / 1000).toFixed(2))); const pin = svg.querySelector("#mpin circle"); if (pin) pin.setAttribute("r", (9 * v.w / 1000).toFixed(2));
