  if (ci < 0) { let bd = 9; MAP.cities.forEach((c, i) => { if (c[1] !== hit[1]) return; const d = Math.hypot(c[2] - hit[2], c[3] - hit[3]); if (d < bd) { bd = d; ci = i; } }); }
