/* ---------- Recent news ---------- */
function newsHTML(sp, t) {
  if (typeof NEWS === "undefined") return "";
  const list = NEWS.filter(n => n[0] === sp.id && (n[1] === t.nick || t.n.endsWith(" " + n[1])));
  const src = { nba: ["ESPN NBA transactions", "https://www.espn.com/nba/transactions"], nhl: ["ESPN NHL transactions", "https://www.espn.com/nhl/transactions"], nfl: ["ESPN NFL transactions", "https://www.espn.com/nfl/transactions"], mlb: ["ESPN MLB transactions", "https://www.espn.com/mlb/transactions"] }[sp.id];
  if (!src) return "";
  return `<h3>Recent news</h3>${list.length ? `<ul class="news">${list.map(n => `<li><span class="num muted">${esc(n[2])}</span> ${esc(n[3])}</li>`).join("")}</ul>` : `<p class="muted">No trades, signings or roster moves in the last few weeks.</p>`}
    <p class="muted">Moves since mid-October. For the latest, see <a class="more" href="${src[1]}" target="_blank" rel="noopener">${src[0]}</a>.</p>`;
}
function newsPanel(sp, t) { const h = newsHTML(sp, t); return h ? `<section class="panel">${h.replace("<h3>Recent news</h3>", "<h2>Recent news</h2>")}</section>` : ""; }

/* ---------- Every team and its players (on each sport page) ---------- */
const GLANCE = { nba: ["PG", "SG", "SF", "PF", "C"], nfl: ["QB", "RB", "WR", "TE", "DL", "LB", "CB"], nhl: ["C", "LW", "RW", "D", "G"], mlb: ["SP", "C", "SS", "CF", "DH", "CL"] };
function teamsGridHTML(sp) {
  const want = GLANCE[sp.id]; if (!want) return "";
  const info = POS_INFO[sp.id];
  const cards = sp.teams.slice().sort((a, b) => a.n.localeCompare(b.n)).map(t => {
    const list = lineupOf(sp, t), rows = want.map(k => { const ps = list.filter(p => ((info.map && info.map[p.pos]) || p.pos) === k && (sp.id !== "nhl" || p.line === 1 || k === "G" && p.line === 1)); const p = ps.find(x => x.star) || ps[0]; return p ? `<li><span class="pk" title="${esc(info[k][0])}">${esc(info[k][0])}</span><span title="${esc(p.n)}">${esc(p.n)}</span></li>` : ""; }).join("");
    return `<article class="panel tglance" style="${colors(t)}"><div class="tghead">${badge(t, "")}<h3><a href="${teamHref(t)}">${esc(t.n)}</a></h3></div>${t.face && t.face[0] ? `<p class="muted">Star: ${esc(t.face[0])}</p>` : ""}<ul class="tgl">${rows}</ul><a class="more" href="${teamHref(t)}">Full line-up and team page</a></article>`;
  }).join("");
  return `<section class="stack" id="all-teams"><div><h2>Every team and its players</h2><p class="hint">The usual starters for every ${esc(sp.word)} team, in alphabetical order. Open a team for the full line-up and what each position does.</p></div><div class="wgrid tgrid">${cards}</div></section>`;
}

/* ---------- Line up the insides of cards that sit side by side ----------
   For every grid of cards, cards on the same row get matching heights for each matching part
   (tags, title, subtitle, each fact), so headings and facts start at the same height. */
function alignCards() {
  /* Three passes so the browser lays the page out once: clear old heights, measure everything, then write. */
  const partsOf = c => [...c.children].flatMap(ch => (ch.tagName === "DL" || ch.classList.contains("tgl")) ? [...ch.children] : ch.classList.contains("links") || ch.classList.contains("go") || ch.classList.contains("more") ? [] : [ch]);
  const grids = [...document.querySelectorAll(".lgrid, .wgrid, .tiles, .sportgrid, .plist")].map(g => ({ cards: [...g.children].map(c => ({ c, parts: partsOf(c) })) }));
  grids.forEach(g => g.cards.forEach(x => x.parts.forEach(p => { if (p.style.minHeight) p.style.minHeight = ""; })));
  const writes = [];
  grids.forEach(g => {
    const rows = {};
    g.cards.forEach(x => { const r = x.c.getBoundingClientRect(); if (!r.height) return; const k = Math.round(r.top); (rows[k] = rows[k] || []).push(x); });
    Object.values(rows).forEach(row => {
      if (row.length < 2) return;
      const n = Math.min(...row.map(x => x.parts.length));
      for (let i = 0; i < n; i++) {
        const tag = row[0].parts[i].tagName; if (row.some(x => x.parts[i].tagName !== tag)) break;
        const hs = row.map(x => x.parts[i].getBoundingClientRect().height), h = Math.max(...hs);
        row.forEach((x, j) => { if (hs[j] < h - 0.5) writes.push([x.parts[i], h]); });
      }
    });
  });
  writes.forEach(([el, h]) => { el.style.minHeight = h + "px"; });
}
let _alignT = 0;
window.addEventListener("resize", () => { clearTimeout(_alignT); _alignT = setTimeout(alignCards, 120); });
if (document.fonts && document.fonts.ready) document.fonts.ready.then(alignCards);

/* Small maps on league and team pages (added v34): where a league's teams play, and where one team sits among its rivals.
   Each links to the full map, zoomed to that league or that town. */
function leagueMapItems(id) {
  if (typeof MAP === "undefined") return [];
  const pre = "#team-" + id + "-";
  return MAP.items.map((it, i) => [it, i]).filter(x => x[0][2] && x[0][2].startsWith(pre) && x[0][4] != null);
}
function leagueMapBox(idx, ar, forceR) {
  ar = ar || 10 / 7;
  /* The most common region among the league's teams, and the box around their cities in that region. */
  const cnt = {}; idx.forEach(i => { const r = itemRegion(i); if (r != null) cnt[r] = (cnt[r] || 0) + 1; });
  const r = forceR != null ? forceR : +Object.keys(cnt).sort((a, b) => cnt[b] - cnt[a])[0];
  const set = new Set(idx);
  const cities = MAP.cities.map((c, ci) => [c, ci, c[4].filter(i => set.has(i))]).filter(x => x[0][1] === r && x[2].length);
  if (!cities.length) return null;
  let x0 = Math.min(...cities.map(c => c[0][2])), x1 = Math.max(...cities.map(c => c[0][2])), y0 = Math.min(...cities.map(c => c[0][3])), y1 = Math.max(...cities.map(c => c[0][3]));
  let w = Math.max(140, (x1 - x0) * 1.25 + 30), h = Math.max(98, (y1 - y0) * 1.25 + 30);
  if (w / h < ar) w = h * ar; else h = w / ar;
  if (h > 700) { h = 700; w = h * ar; }
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  return { r, cities, v: { x: cx - w / 2, y: cy - h / 2, w, h } };
}
function miniMapSVG(box, focusCity, label) {
  const v = box.v, k = v.w / 1000;
  const dots = box.cities.slice().sort((a, b) => (a[1] === focusCity) - (b[1] === focusCity) || a[2].length - b[2].length).map(([c, ci, its]) => {
    const on = focusCity == null || ci === focusCity, base = (focusCity == null ? 5.5 + Math.sqrt(its.length - 1) * 1.6 : on ? 8 : 5) * 1.9;
    const names = its.map(i => MAP.items[i][0]).join(", ");
    return `<circle class="mmdot${on ? " on" : ""}" cx="${c[2]}" cy="${c[3]}" r="${(base * k).toFixed(2)}" style="stroke-width:${(0.8 * k).toFixed(2)}" data-act="mmdot" data-id="${ci}" tabindex="0" role="button" aria-label="${esc(c[0].split(",")[0])}: ${esc(names)}"><title>${esc(c[0])}: ${esc(names)}</title></circle>`
      + (on && focusCity != null ? `<circle class="mring" cx="${c[2]}" cy="${c[3]}" r="${(24 * k).toFixed(2)}" style="stroke-width:${(2.2 * k).toFixed(2)}"/>` : "");
  }).join("");
  return `<svg class="minimap" viewBox="${v.x.toFixed(1)} ${v.y.toFixed(1)} ${v.w.toFixed(1)} ${v.h.toFixed(1)}" role="img" aria-label="${esc(label)}">
    <rect x="-5000" y="-5000" width="11000" height="11000" class="sea"/>
    <path class="land" style="stroke-width:${k.toFixed(3)}" d="${[MAP.na, MAP.eu, MAP.as, MAP.au, MAP.sa, MAP.af][box.r]}"/>${box.r ? "" : `<path class="borders" style="stroke-width:${k.toFixed(3)}" d="${MAP.naStates}"/>`}
    ${dots}</svg>`;
}
function leagueMapPanel(sp) {
  const items = leagueMapItems(sp.id); if (items.length < 2) return "";
  const box = leagueMapBox(items.map(x => x[1]), 16 / 9); if (!box) return "";
  const big = box.cities.slice().sort((a, b) => b[2].length - a[2].length)[0];
  const n = new Set(items.map(x => x[0][3])).size;
  const tops = box.cities.filter(c => c[2].length === big[2].length).map(c => c[0][0].split(",")[0]);
  const most = big[2].length < 2 ? "" : tops.length === 1 ? ` ${esc(tops[0])} has the most, with ${big[2].length}.` : tops.length <= 3 ? ` ${esc(tops.slice(0, -1).join(", "))} and ${esc(tops[tops.length - 1])} have the most, with ${big[2].length} each.` : "";
  return `<section class="panel" id="league-map">
    <h2>Where the teams play</h2>
    <p class="hint">Every ${esc(sp.name)} team on the map. Teams from the same city share one dot.${most}</p>
    <div class="miniwrap wide">${miniMapSVG(box, null, "Map of where the " + sp.name + " teams play")}</div>
    <div class="mminfo" id="mminfo" data-lg="${esc(sp.id)}" aria-live="polite"><p class="muted">Select a dot to see the teams in that city.</p></div>
    <p><a class="more" href="#near-${esc(sp.id)}">Open the full map with only these teams</a></p>
  </section>`;
}
function teamMapPanel(sp, t) {
  const items = leagueMapItems(sp.id), href = "#team-" + sp.id + "-" + t.slug;
  const me = items.find(x => x[0][2] === href); if (!me) return "";
  const box = leagueMapBox(items.map(x => x[1]), 10 / 7, itemRegion(me[1])); if (!box) return "";
  const city = box.cities.find(c => c[2].includes(me[1])); if (!city) return "";
  const town = me[0][3].replace(/\s*\(.*?\)/, "").split(",")[0].trim();
  const same = city[2].filter(i => i !== me[1]).map(i => MAP.items[i][0]);
  const near = items.filter(x => x[1] !== me[1] && !city[2].includes(x[1])).map(x => ({ n: x[0][0], km: kmBetween([me[0][4], me[0][5]], [x[0][4], x[0][5]]) })).sort((a, b) => a.km - b.km)[0];
  const cname = city[0][0].split(",")[0], area = fold(cname) === fold(town) ? esc(town) : `the ${esc(cname)} area`;
  const line = !same.length ? `They are the only ${esc(sp.name)} team in ${area}.` : same.length > 3 ? `${area === esc(town) ? esc(town) : "The " + esc(cname) + " area"} has ${same.length + 1} ${esc(sp.name)} teams, the most of any city in the league, so local rivals are never far away.`.replace(", the most of any city in the league", city[2].length >= Math.max(...box.cities.map(c => c[2].length)) ? ", the most of any city in the league" : "") : `They share ${area} with ${esc(same.length === 1 ? same[0] : same.slice(0, -1).join(", ") + " and " + same[same.length - 1])}.`;
  return `<section class="panel" id="team-map">
    <h2>Where they play</h2>
    <p class="hint">The ring marks ${fold(city[0][0].split(",")[0]) === fold(town) ? esc(town) : esc(town) + ", in the " + esc(city[0][0].split(",")[0]) + " area"}.${box.cities.length > 1 ? ` The smaller dots are the other ${esc(sp.name)} teams.` : ` The other ${esc(sp.name)} teams play in ${esc(MAP_REGIONS[itemRegion(items.find(x => x[1] !== me[1])[1])] || "another part of the world")}.`}</p>
    <div class="miniwrap">${miniMapSVG(box, city[1], "Map of " + town + " among the other " + sp.name + " teams")}</div>
    <p>${line}${near ? ` The closest other team is ${esc(near.n)}, ${esc(kmText(near.km))}.` : ""}</p>
    <p><a class="more" href="#near/${encodeURIComponent(town)}">See every team near ${esc(town)}</a></p>
  </section>`;
}
/* Opening the full map from a league page: show only that league and zoom to its teams. */
function mapOnlyLeague(id) {
  const items = leagueMapItems(id); if (!items.length) return;
  const box = leagueMapBox(items.map(x => x[1])); if (!box) return;
  const lg = items[0][0][1];
  state.mreg = box.r; state.mg = {};
  MAP_GROUPS.filter(g => g[3] === box.r).forEach(g => g[2].forEach(l => { if (l !== lg) state.mg[l] = true; }));
  MV[box.r] = { x: box.v.x, y: box.v.y, w: box.v.w, h: box.v.h }; state.near = "";
}

/* A dot on a league's small map lists that city's teams in the league, with links to their pages. */
function miniInfo(ci) {
  const box = document.getElementById("mminfo"), c = MAP.cities[ci]; if (!box || !c) return;
  const pre = "#team-" + box.dataset.lg + "-";
  const its = c[4].map(i => MAP.items[i]).filter(it => it[2] && it[2].startsWith(pre)).sort((a, b) => a[0].localeCompare(b[0]));
  const city = c[0].split(",")[0];
  box.innerHTML = `<p><b>${esc(city)}</b> · ${its.length} team${its.length === 1 ? "" : "s"}</p><ul class="names">${its.map(it => { const town = it[3].replace(/\s*\(.*?\)/, "").split(",")[0].trim();
    return `<li><a class="more" href="${esc(it[2])}">${esc(it[0])}</a>${town !== city ? ` <span class="muted">${esc(town)}</span>` : ""}</li>`; }).join("")}</ul>`;
  document.querySelectorAll("#league-map .mmdot").forEach(d => d.classList.toggle("sel", d.dataset.id === String(ci)));
  if (typeof applySpelling === "function") applySpelling(box, SPELL_V);
}
document.addEventListener("keydown", e => { const t = e.target; if ((e.key === "Enter" || e.key === " ") && t && t.classList && t.classList.contains("mmdot")) { e.preventDefault(); miniInfo(+t.dataset.id); } });

;
/* ---- browse.js ---- */
/* Rookie Season: browse every team in a league without taking the quiz, with the league's former teams underneath. */
const BROWSE_GROUPS = [["Big four", ["nba", "nfl", "nhl", "mlb"]], ["Women's leagues", ["wnba", "nwsl", "pwhl", "mlv", "nsl", "lovb"]], ["Other leagues", ["mls", "cfl", "nll", "mlr"]]];
/* Two steps, as on Other sports: pick a sport, then one of its leagues. */
function browseGroups() {
  const ok = x => !x.startsWith("g:") && SPORTS[x];
  return sportGroups().map(S => [S.name, S.groups.flatMap(g => g[1]).filter(ok), S.icon, S.groups.map(([l, ids]) => [l, ids.filter(ok)]).filter(g => g[1].length)]).filter(g => g[1].length);
}
/* Columns chosen so every row is full where the count allows it (3 or 2 across), and names stay on one line. */
const bcols = n => n % 3 === 0 ? " three" : n % 2 === 0 ? " two" : " three";
function vBrowse(id) {
  const GROUPS = browseGroups();
  const ids = GROUPS.flatMap(g => g[1]);
  const sp = SPORTS[ids.includes(id) ? id : "nba"];
  const cur = GROUPS.find(g => g[1].includes(sp.id));
  const chips = `<div class="bgroup"><span class="muted">1. Sport</span><div class="chips">${GROUPS.map(([label, list, icon]) =>
    `<a class="chip" href="#browse-${list[0]}" aria-current="${cur === GROUPS.find(g => g[0] === label) ? "page" : "false"}">${sportIcon(icon)}${esc(label)}</a>`).join("")}</div></div>
    ${cur[1].length > 1 ? `<div class="bgroup"><span class="muted">2. League</span>${cur[3].map(([l, list]) => `<div class="bsub">${cur[3].length > 1 ? `<span class="muted">${esc(l)}</span>` : ""}<div class="chips">${list.map(x =>
    `<a class="chip" href="#browse-${x}" aria-current="${x === sp.id ? "page" : "false"}">${esc(SPORTS[x].name)}</a>`).join("")}</div></div>`).join("")}</div>` : ""}`;
  const card = t => `<a class="bteam" title="${esc(t.n + " · " + t.city)}" href="${teamHref(t)}" style="--c1:${t.c[0]}">${badge(t)}<span><b>${esc(t.n)}</b><small>${esc(t.city)}</small><small>${t.titles ? `${t.titles} ${esc(t.titles === 1 ? sp.titleLabel.replace(/s$/, "") : sp.titleLabel)}` : t.isNew ? "New team" : "No titles yet"}</small></span></a>`;
  const confs = sp.confs.map(([code, name]) => { const list = sp.teams.filter(t => t.conf === code).sort((a, b) => a.n.localeCompare(b.n));
    return list.length ? `<section class="stack"><h3 class="bconf">${esc(name)} <span class="muted">${list.length} teams</span></h3><div class="bgrid${bcols(list.length)}">${list.map(card).join("")}</div></section>` : ""; }).join("");
  const gone = typeof ARCHIVE === "undefined" ? [] : ARCHIVE.filter(a => a[0] === sp.name);
  return `
  <section class="hero">
    <p class="eyebrow">Browse every team</p>
    <h1>Every team, no quiz.</h1>
    <p class="lede">Already have a team in mind, or just want to look around? Pick a league to see all of its teams. Open any team for its story, stars and where to watch.</p>
    ${chips}
  </section>
  <section class="stack">
    <div class="sec-head"><h2>${sportIcon(sp.id)} ${esc(sp.name)}</h2><p class="muted">${sp.teams.length} teams · <a class="more" href="#${sp.id}">Help me choose one</a></p></div>
  </section>
  ${confs}
  ${sp.quick ? "" : `<section class="stack" id="gone">
    <div><h2>Teams that are gone</h2><p class="hint">${gone.length ? `${esc(sp.name)} teams that moved, folded or stopped playing.` : `No ${esc(sp.name)} teams have moved or folded in recent times.`}</p></div>
    ${gone.length ? `<div class="tablebox"><table><thead><tr><th>Team</th><th>Years</th><th>What happened</th></tr></thead><tbody>${gone.map(a => `<tr><td><b>${esc(a[1])}</b></td><td class="num">${esc(a[2])}</td><td>${esc(a[3])}</td></tr>`).join("")}</tbody></table></div>` : ""}
  </section>`}`;
}

/* A team that folded after the 2026 volleyball season. */
if (typeof ARCHIVE !== "undefined") ARCHIVE.push(["MLV", "San Diego Mojo", "2024–2026", "Stopped playing after reaching the 2026 playoffs."]);

/* Show the menu bar on the home page once "Pick a sport" reaches the top of the screen. */
(function () {
  let raf = 0;
  const check = () => { raf = 0; const b = document.body; if (b.dataset.view !== "home") { b.classList.remove("show-top"); return; }
    const pick = document.getElementById("pick-sport"); b.classList.toggle("show-top", !!pick && pick.getBoundingClientRect().top < 90); };
  addEventListener("scroll", () => { if (!raf) raf = requestAnimationFrame(check); }, { passive: true });
  addEventListener("hashchange", () => setTimeout(check, 0));
  addEventListener("load", check);
})();

