/* ---- soccer.js ---- */
/* Rookie Season: soccer players (MLS and the top five European leagues).
   Squads come from data-socp.js. Players join the shared player list (sport id "soc"),
   and every club gets a card with its squad by position on the MLS page and on each European league. */
const SOC_LG = { mls: "MLS", eng: "Premier League", esp: "La Liga", ita: "Serie A", ger: "Bundesliga", fra: "Ligue 1", ned: "Eredivisie", por: "Primeira Liga", sco: "Scottish Premiership", ligamx: "Liga MX" };
const SOC_POS = { GK: "Goalkeeper", DF: "Defender", MF: "Midfielder", FW: "Forward" };
const SOC_POS_PL = { GK: "Goalkeepers", DF: "Defenders", MF: "Midfielders", FW: "Forwards" };
const HAS_SOC = typeof SOC_SQ !== "undefined";

/* The best-known player at each club (v42): shown first on club cards and team pages, and used by the fan quiz. Only names in a squad count. */
const SOC_STARS = new Set(("Lionel Messi;Luis Suárez;Rodrigo De Paul;Son Heung-min;Denis Bouanga;Thomas Müller;Hirving Lozano;Evander;Riqui Puig;Emil Forsberg;Christian Benteke;Cucho Hernández;Diego Rossi;Sam Surridge;Hany Mukhtar;Brian White;" +
  "Erling Haaland;Phil Foden;Rayan Cherki;Bukayo Saka;Declan Rice;Martin Ødegaard;William Saliba;Viktor Gyökeres;Florian Wirtz;Alexander Isak;Virgil van Dijk;Dominik Szoboszlai;Cole Palmer;Moisés Caicedo;Bruno Fernandes;Bryan Mbeumo;Matheus Cunha;Xavi Simons;Mohammed Kudus;Micky van de Ven;Bruno Guimarães;Anthony Elanga;Alejandro Garnacho;John McGinn;Jordan Pickford;Jack Grealish;Adam Wharton;Jean-Philippe Mateta;Morgan Gibbs-White;Kaoru Mitoma;Justin Kluivert;Igor Thiago;Alex Iwobi;Granit Xhaka;Dominic Calvert-Lewin;Haji Wright;Leif Davis;" +
  "Lamine Yamal;Pedri;Raphinha;Rodri;Kylian Mbappé;Vinícius Júnior;Jude Bellingham;Thibaut Courtois;Federico Valverde;Julián Alvarez;Jan Oblak;Koke;Nico Williams;Mikel Oyarzabal;Takefusa Kubo;Gerard Moreno;Isco;Antony;José Gayà;Iago Aspas;" +
  "Lautaro Martínez;Nicolò Barella;Luka Modrić;Christian Pulisic;Mike Maignan;Kenan Yıldız;Kevin De Bruyne;Scott McTominay;Paulo Dybala;Nico Paz;" +
  "Harry Kane;Jamal Musiala;Michael Olise;Joshua Kimmich;Serhou Guirassy;Gregor Kobel;" +
  "Ousmane Dembélé;Vitinha;Achraf Hakimi;Désiré Doué;Mason Greenwood;Pierre-Emerick Aubameyang;Alexandre Lacazette;Corentin Tolisso;Paul Pogba;Takumi Minamino;Aleksandr Golovin;Terem Moffi;Florian Thauvin;Ludovic Blas;Hákon Arnar Haraldsson;Jonathan David;Wahbi Khazri;Romain Del Castillo;Gaëtan Laborde;" +
  "Charles De Ketelaere;Gianluca Scamacca;Mattia Zaccagni;Ciro Immobile;Moise Kean;David de Gea;Riccardo Orsolini;Duván Zapata;Keinan Davis;Nikola Krstović;Andrea Pinamonti;Domenico Berardi;Lorenzo Pellegrini;Artem Dovbyk;Dušan Vlahović;Marcus Thuram;Hakan Çalhanoğlu;Yann Sommer;Ange-Yoan Bonny;Ademola Lookman;Gian Piero Gasperini;" +
  "Patrik Schick;Florian Wirtz;Deniz Undav;Can Uzun;Mario Götze;Vincenzo Grifo;Tim Kleindienst;Andrej Kramarić;Marvin Ducksch;Jonathan Burkardt;Robert Andrich;Granit Xhaka;Loïs Openda;David Raum;Benjamin Šeško;Leroy Sané;Marc-André ter Stegen;Ante Budimir;Javi Puado;Borja Iglesias;Isi Palazón;Álvaro Morata;Mikel Merino;Youssef En-Nesyri;Enes Ünal;Umar Sadiq;Hugo Duro;Dani Parejo;Iñaki Williams;Oihan Sancet;Alberto Moleiro;Robin Le Normand;Antoine Griezmann;Ayoze Pérez").split(";"));
/* Other names a player is searched by. */
const SOC_AKA = { "Rodri": "Rodrigo Hernández Cascante", "Pedri": "Pedro González López", "Gavi": "Pablo Gavira", "Vinícius Júnior": "Vinicius Jr", "Estêvão": "Estevao Willian", "Koke": "Jorge Resurrección", "Isco": "Francisco Román Alarcón" };
/* Club names that differ between the squad lists and the league tables. */
const SOC_CLUB_ALIAS = { "Hamburger SV": "Hamburg SV", "1. FC Köln": "FC Cologne", "Rennes": "Stade Rennais" };
const socKey = s => fold(s).replace(/\b(fc|cf|afc|ac|as|ss|ssc|sc|1\.|tsg|vfb|vfl|rb|ogc|rc|aj|club|de|calcio)\b/g, "").replace(/[^a-z0-9]/g, "");
function socTeam(s) {
  const sp = SPORTS[s.lg]; if (!sp) return null;
  if (s.lg === "mls") return sp.teams.find(x => x.a === s.club) || null;
  const want = SOC_CLUB_ALIAS[s.club] || s.club, k = socKey(want);
  return sp.teams.find(x => x.n === want) || sp.teams.find(x => socKey(x.n) === k) || sp.teams.find(x => socKey(x.n).includes(k) || k.includes(socKey(x.n))) || null;
}
if (HAS_SOC) {
  Object.values(SOC_NAT).forEach(([n, iso]) => { if (!ISO[n]) ISO[n] = iso; });
  SOC_SQ.forEach(s => {
    const t = socTeam(s);
    s.team = t;
    s.list = s.p.split(";").map(r => { const q = r.split(","), code = q.pop(), pos = q.pop(), n = q.join(","); return { n, pos, c: SOC_NAT[code] ? SOC_NAT[code][0] : "", star: SOC_STARS.has(n) }; });
    s.list.forEach(p => ALLP.push({ n: p.n, k: fold(p.n + (SOC_AKA[p.n] ? " " + SOC_AKA[p.n] : "")), sp: "soc", t, club: t ? t.n : s.club, lg: s.lg, town: "", place: "", c: p.c, note: "", pos: SOC_POS[p.pos], roots: null, former: [], star: p.star }));
    /* A club page with no headline player yet shows its best-known one. */
    if (t && (!t.face || !t.face[0])) {
      const order = ["FW", "MF", "DF", "GK"], best = s.list.filter(p => p.star).sort((a, b) => order.indexOf(a.pos) - order.indexOf(b.pos))[0];
      if (best) t.face = [best.n, `${SOC_POS[best.pos]}${best.c ? ", " + best.c : ""}`];
    }
  });
  P_SPORTS.push("soc");
}
const spLabel = id => id === "soc" ? "Soccer" : id === "mlr" ? "MLR" : ["wnba", "nwsl", "nsl", "pwhl", "cfl", "mlr"].includes(id) && SPORT_INFO[id] ? SPORT_INFO[id].word : SPORT_INFO[id] ? SPORT_INFO[id].sport : id.toUpperCase();
const spIcon = id => sportIcon(id === "soc" ? "mls" : id);

function socCard(p, showSport) {
  const t = p.t, href = t ? teamHref(t) : `#soccer-${p.lg}`;
  return `<article class="pcard" style="${t ? colors(t) : ""}">
    ${showSport ? `<div class="tags"><span class="tag">${esc(pLeague(p))}</span></div>` : ""}
    <h3>${esc(p.n)}</h3>
    ${p.c ? `<p class="from">Nationality: ${flag(p.c)} ${esc(p.c)}</p>` : ""}
    <p>Plays for <a class="more" href="${href}">${esc(p.club)}</a></p>
    <p class="from">${esc(SOC_LG[p.lg] || "")} · ${esc(p.pos || "")}</p>
  </article>`;
}

/* One card per club: two or three names for each position, then the full squad on request. */
function socClubCard(s) {
  const t = s.team, name = t ? t.n : s.club;
  const rows = ["GK", "DF", "MF", "FW"].map(k => { const l = s.list.filter(p => p.pos === k); if (!l.length) return "";
    /* One name per line keeps every row on one line; the rest are in the full squad below. */
    const lead = l.find(p => p.star) || l[0], show = esc(lead.n);
    return `<li><span class="pk">${k === "GK" ? "Goalkeeper" : SOC_POS_PL[k]}</span><span>${show}</span></li>`; }).join("");
  const full = ["GK", "DF", "MF", "FW"].map(k => { const l = s.list.filter(p => p.pos === k); return l.length ? `<p><b>${SOC_POS_PL[k]}:</b> ${l.map(p => `${esc(p.n)}${p.c ? " " + flag(p.c) : ""}`).join(", ")}</p>` : ""; }).join("");
  const nations = new Set(s.list.map(p => p.c).filter(Boolean)).size;
  return `<article class="panel tglance"${t ? ` style="${colors(t)}"` : ""}>
    <div class="tghead">${t ? badge(t, "") : ""}<h3>${t ? `<a href="${teamHref(t)}">${esc(name)}</a>` : esc(name)}</h3></div>
    <p class="muted">${s.list.length} players from ${nations} ${nations === 1 ? "country" : "countries"}</p>
    <ul class="tgl soc">${rows}</ul>
    <details class="squad"><summary>Full squad</summary><div>${full}</div></details>
  </article>`;
}
function socClubsHTML(lg, title, hint) {
  if (!HAS_SOC) return "";
  const clubs = SOC_SQ.filter(s => s.lg === lg).slice().sort((a, b) => (a.team ? a.team.n : a.club).localeCompare(b.team ? b.team.n : b.club));
  if (!clubs.length) return "";
  const L = typeof EURO_LEAGUES !== "undefined" && EURO_LEAGUES.find(x => x.id === lg);
  const missing = L ? L.table.map(r => r.n).filter(n => !clubs.some(s => s.club === n)) : [];
  const note = missing.length ? ` Not listed yet: ${missing.join(", ")} (no up-to-date squad was available).` : "";
  return `<section class="stack" id="all-teams"><div><h2>${esc(title)}</h2><p class="hint">${esc(hint + note)}</p></div><div class="wgrid tgrid">${clubs.map(socClubCard).join("")}</div></section>`;
}

/* MLS page: the soccer version of "Every team and its players". */
const _teamsGrid = teamsGridHTML;
teamsGridHTML = function (sp) {
  if (sp.id === "mls") return socClubsHTML("mls", "Every team and its players", "Each club's first-team squad, in alphabetical order. One name per position, then the full squad with each player's country.");
  return _teamsGrid(sp);
};
/* European leagues: every club's squad under the table. */
const _leagueHTML = leagueHTML;
leagueHTML = function (L) {
  const html = _leagueHTML(L), grid = socClubsHTML(L.id, "Every club and its players", "Each club's first-team squad, in alphabetical order. One name per position, then the full squad with each player's country.");
  return grid ? html.replace(/<\/div>\s*$/, grid + "</div>") : html;
};

