const ROSTER_SRC = { cfl: "Stats Crew: players who appeared in a 2026 game (offensive linemen are often missing because they rarely record statistics)", mlr: "each club's Wikipedia page", pwhl: "each team's Wikipedia page (2026–27 rosters)", nwsl: "each club's Wikipedia page", nsl: "each club's Wikipedia page", nhl: "ESPN, Wikipedia and Hockey-Reference 2026–27 rosters", wnba: "Basketball-Reference 2026 season rosters (many players become free agents in the off-season)", nba: "ESPN team rosters", nfl: "ESPN team rosters, including the practice squad and injured players", mlb: "MLB.com 40-man rosters", mls: "each club's Wikipedia page", khl: "each club's Wikipedia page", euroleague: "the EuroLeague's official team rosters" };
function rosterHTML(sp, t) {
  const list = rosterOf(sp, t); if (list.length < 5) return "";
  const order = ROSTER_ORDER[sp.id], byLast = (a, b) => a.n.split(" ").slice(-1)[0].localeCompare(b.n.split(" ").slice(-1)[0]) || a.n.localeCompare(b.n);
  const groups = new Map();
  if (order) order.forEach(([c]) => groups.set(c, []));
  list.slice().sort(byLast).forEach(p => { const g = order ? (order.some(o => o[0] === p.rpos) ? p.rpos : "?") : (p.pos || "Other"); if (!groups.has(g)) groups.set(g, []); groups.get(g).push(p.n); });
  const label = g => order ? ((order.find(o => o[0] === g) || [0, "Others"])[1]) : g;
  const body = [...groups].filter(([, ns]) => ns.length).map(([g, ns]) => `<p><b>${esc(label(g))}:</b> ${ns.map(esc).join(", ")}</p>`).join("");
  return `<details class="squad"><summary>Full roster (${list.length} players)</summary><div>${body}<p class="muted">${["ned", "por", "sco", "ligamx"].includes(sp.id) ? "From each club's Wikipedia or ESPN page, Nov 20, 2026." : ["eng", "esp", "ita", "ger", "fra"].includes(sp.id) ? "From each club's Wikipedia page (Nov 16, 2026), with the biggest clubs checked again against ESPN on Nov 20, 2026. Players out on loan are listed with the club they play for now." : `From ${esc(ROSTER_SRC[sp.id] || "team rosters")}, ${["khl", "euroleague"].includes(sp.id) ? "Nov 20" : "Nov 16"}, 2026.`} Rosters change often.</p></div></details>`;
}

/* Line-up players who are on no roster now (mostly baseball free agents after the 2026 season) are marked on team pages. */
(function () {
  const free = new Set(ALLP.filter(p => p.free).map(p => p.sp + ":" + nameKey(p.n)));
  Object.keys(LU).forEach(id => Object.keys(LU[id]).forEach(a => LU[id][a].forEach(p => { if (free.has(id + ":" + nameKey(p.n))) p.gone = true; })));
})();

/* Hockey sources spell some names differently (Cam/Cameron York, J. T./J.T. Miller): one player per team and surname. */
(function () {
  const groups = new Map(), drop = new Set();
  ALLP.forEach(p => { if (p.sp !== "nhl" || !p.t) return; const parts = nameKey(p.n).split(" "), last = parts.pop(), first = parts.join("");
    const k = p.t.a + ":" + last; if (!groups.has(k)) groups.set(k, []); groups.get(k).push({ p, first, one: parts.length === 1, sig: parts[0] + parts.slice(1).map(x => x[0]).join("") }); });
  groups.forEach(list => { for (let i = 0; i < list.length; i++) for (let j = i + 1; j < list.length; j++) {
    const a = list[i], b = list[j]; if (drop.has(a.p) || drop.has(b.p) || !(a.first === b.first || a.sig === b.sig || (a.one && b.one && a.first.slice(0, 2) === b.first.slice(0, 2)))) continue;
    const keep = a.p.town || !b.p.town ? a.p : b.p, gone = keep === a.p ? b.p : a.p;
    ["pos", "rpos", "c", "town", "place"].forEach(f => { if (!keep[f] && gone[f]) keep[f] = gone[f]; }); drop.add(gone); } });
  if (drop.size) { const kept = ALLP.filter(p => !drop.has(p)); ALLP.length = 0; kept.forEach(p => ALLP.push(p)); }
})();

