const RIVALRIES = [
  ["celtics-lakers", "Celtics and Lakers", "The NBA's biggest rivalry", "nba", "BOS", "LAL", "Twice a season, once in each city, because they play in different conferences. They can only meet in the playoffs in the NBA Finals.",
    "The two most successful teams in NBA history, on opposite coasts. They have met in the NBA Finals 12 times, more than any other pair, and between them they have won close to half of all NBA championships.",
    ["In the 1960s, Bill Russell's Celtics beat the Lakers in the Finals six times.", "In the 1980s, Larry Bird's Celtics and Magic Johnson's Lakers met in three Finals and rescued the league's popularity.", "The Lakers won the last Finals meeting, in 2010, in a deciding seventh game."]],
  ["yankees-red-sox", "Yankees and Red Sox", "Baseball's oldest grudge", "mlb", "NYY", "BOS", "About 13 times a season, because they share the American League East division.",
    "New York and Boston have competed in everything for centuries, and baseball made it personal. After Boston sold Babe Ruth to New York in 1920, the Yankees became baseball's dominant team and the Red Sox did not win another World Series for 86 years.",
    ["In 2003, the Yankees won the American League final with a home run in extra innings of the seventh game.", "In 2004, the Red Sox became the first team in baseball history to come back from three games down in a best-of-seven series, against the Yankees, and then won the World Series.", "Their games are long, tense and sold out, even in years when neither team is very good."]],
  ["canadiens-maple-leafs", "Canadiens and Maple Leafs", "Hockey's oldest rivalry", "nhl", "MTL", "TOR", "Three or four times a season, because they share the Atlantic Division.",
    "Canada's two most famous teams, from its two largest cities, one French-speaking and one English-speaking. For decades they were the only Canadian teams in the NHL, and supporting one or the other said a lot about where a fan came from.",
    ["Montréal has won more Stanley Cups than any other team.", "Toronto beat Montréal in the 1967 Stanley Cup Final. It remains the Maple Leafs' last championship.", "Their 2021 playoff meeting went to a seventh game, and Montréal won it."]],
  ["bears-packers", "Bears and Packers", "The NFL's oldest rivalry", "nfl", "CHI", "GB", "Twice a season, because they share the NFC North division.",
    "The most-played rivalry in NFL history, first played in 1921, between a big city and the league's smallest market. Both clubs were built by founders who shaped the early NFL, and their games are often played in snow and freezing cold.",
    ["Green Bay went ahead in the all-time series in 2017 and has led since.", "Packers quarterbacks Brett Favre and Aaron Rodgers won most of their games against Chicago across almost 30 years.", "The two teams met in the NFC Championship game after the 2010 season, which Green Bay won on the way to the Super Bowl."]],
  ["old-firm", "Celtic and Rangers", "The Old Firm, in Glasgow", "sco", "CEL", "RAN", "Four times a season in the Scottish Premiership, and often again in cup competitions.",
    "Two clubs from the same city that have won almost every Scottish championship between them. The rivalry has deep roots in Glasgow's history, with Celtic founded to raise money for poor Irish Catholic immigrants and Rangers traditionally supported by the Protestant community.",
    ["Celtic became the first British club to win the European Cup, in 1967.", "Rangers went out of business in 2012, restarted in the fourth tier and returned to the top division in 2016.", "Rangers' 2021 title stopped Celtic from winning a record 10 championships in a row."]],
  ["superclasico", "Boca and River", "The Superclásico, in Buenos Aires", "arg", "BOC", "RIV", "At least once a season in the league, and in cup games when the draw brings them together.",
    "Both clubs were born in the working-class port district of La Boca. River moved to the wealthier north of the city, and the rivalry grew into the biggest in South American soccer, often called the most passionate derby in the world.",
    ["Boca's fans are known as Xeneizes, and River's club is nicknamed Los Millonarios, the millionaires.", "In 2018 they met in the final of the Copa Libertadores, South America's top club competition. The deciding game was moved to Madrid after an attack on Boca's team bus, and River won.", "Boca's stadium, La Bombonera, is famous for shaking when the crowd jumps."]],
  ["el-clasico", "Real Madrid and Barcelona", "El Clásico", "esp", "REA", "BSC", "Twice a season in La Liga, and often in the Spanish cup, the Spanish Super Cup or the Champions League.",
    "Spain's two biggest clubs, from its capital and from Catalonia, a region with its own language and a strong identity of its own. Their meetings are among the most watched club games in the world.",
    ["Alfredo Di Stéfano chose Madrid over Barcelona in 1953 after a disputed transfer, and led Madrid to five European Cups in a row.", "Luís Figo moved from Barcelona to Madrid in 2000, and Barcelona's fans have never forgiven him.", "From 2009 to 2018, Lionel Messi and Cristiano Ronaldo faced each other in these games several times a year."]],
  ["liverpool-man-utd", "Liverpool and Man United", "England's biggest rivalry", "eng", "LIV", "MUN", "Twice a season in the Premier League, and sometimes in the FA Cup or the League Cup.",
    "The two most successful clubs in English history, from two north-western cities that have competed since the Industrial Revolution. Each club measures itself against the other's number of league titles.",
    ["Manchester United won most of the titles in the 1990s and 2000s under Sir Alex Ferguson.", "Liverpool won most of them in the 1970s and 1980s, and won the Premier League again in 2020 and 2025.", "The fixture sells out every year, whatever the two clubs' form."]],
  ["cairo-derby", "Al Ahly and Zamalek", "The Cairo derby", "egy", "AHL", "ZAM", "Twice a season in the Egyptian Premier League, and often in cup finals.",
    "The two most successful clubs in Africa, from the same city. The rivalry is so intense that the games are often played with foreign referees, and sometimes without fans.",
    ["Al Ahly was founded in 1907, and Zamalek in 1911.", "In 2020 they met in the final of the CAF Champions League, Africa's top club competition, for the first time. Al Ahly won 2–1.", "Between them they have won most of Egypt's league titles."]],
  ["battle-of-alberta", "Oilers and Flames", "The Battle of Alberta", "nhl", "EDM", "CGY", "Three or four times a season, because they share the Pacific Division.",
    "Edmonton and Calgary are the two largest cities in Alberta, about three hours apart, and they have argued about everything for over a century. On the ice, the rivalry peaked in the 1980s: one of the two teams played in every Stanley Cup Final from 1983 to 1990.",
    ["Wayne Gretzky's Oilers won four Stanley Cups in the 1980s, and the Flames won in 1989.", "In 1986, an Oilers defenceman scored into his own net in the seventh game of a playoff series, and Calgary went through.", "In 2022 they met in the playoffs for the first time in 31 years. Connor McDavid scored the overtime goal that sent Edmonton through."]],
  ["dodgers-giants", "Dodgers and Giants", "From New York to California", "mlb", "LAD", "SF", "About 13 times a season, because they share the National League West division.",
    "The rivalry began in New York in the 1880s, when the Dodgers played in Brooklyn and the Giants in Manhattan. Both teams moved to California in 1958, and the rivalry moved with them, now between Los Angeles and San Francisco.",
    ["In 1951, the Giants' Bobby Thomson hit a home run to win the pennant against the Dodgers, known as the Shot Heard 'Round the World.", "Between them they have won over 40 National League pennants.", "In 2021 they met in the playoffs for the first time, after both won over 100 games. The Dodgers won the series in five games."]],
  ["soweto-derby", "Chiefs and Pirates", "The Soweto derby", "rsa", "KAI", "ORL", "Twice a season in the league, and in cup games.",
    "Both clubs come from Soweto, the large township near Johannesburg. Kaizer Chiefs was founded in 1970 by Kaizer Motaung, a former Orlando Pirates player, and the two clubs are the most supported in South Africa.",
    ["Their games fill FNB Stadium in Johannesburg, the biggest stadium in Africa, with crowds of up to about 90,000.", "Orlando Pirates won the CAF Champions League in 1995, the first South African club to do so.", "Fans wear black and gold for Chiefs and black and white for Pirates."]]
];
const rivalById = id => RIVALRIES.find(r => r[0] === id);
const rivalsOfTeam = (sp, t) => RIVALRIES.filter(r => r[3] === sp.id && (r[4] === t.a || r[5] === t.a));
function rivalTeams(r) { const sp = SPORTS[r[3]]; if (!sp) return null; const a = sp.teams.find(t => t.a === r[4]), b = sp.teams.find(t => t.a === r[5]); return a && b ? { sp, a, b } : null; }
function vRivalries() {
  const cards = RIVALRIES.filter(rivalTeams).map(r => { const { sp, a, b } = rivalTeams(r);
    return `<a class="rvcard" href="#rivalry-${r[0]}"><div class="rvbadges">${badge(a, "big")}<span class="rvvs">v</span>${badge(b, "big")}</div><p class="eyebrow">${esc(sp.name)}</p><h3>${esc(r[1])}</h3><p class="muted">${esc(r[2])}</p></a>`; }).join("");
  return `
  <section class="hero">
    <p class="eyebrow">Rivalries</p>
    <h1>The games that matter most.</h1>
    <p class="lede">Every sport has a few games that mean more than the rest. Learn the story behind the great rivalries, so you know why everyone is excited when they meet.</p>
  </section>
  <div class="rvgrid">${cards}</div>`;
}
function vRivalry(id) {
  const r = rivalById(id), x = r && rivalTeams(r); if (!x) return vRivalries();
  const { sp, a, b } = x, lbl = sp.titleLabel || "Championships";
  const side = t => `<a class="rvteam" href="${teamHref(t)}" style="${colors(t)}">${badge(t, "big")}<div><h3>${esc(t.n)}</h3><p class="muted">${esc(t.city)}</p><p><b>${esc(lbl)}:</b> ${t.titles || 0}</p></div></a>`;
  return `
  <a class="back" href="#rivalries">← All rivalries</a>
  <section class="hero">
    <p class="eyebrow">${esc(sp.name)}</p>
    <h1>${esc(r[1])}.</h1>
    <p class="lede">${esc(r[2])}.</p>
  </section>
  <div class="rvpair">${side(a)}<span class="rvvs big">v</span>${side(b)}</div>
  <section class="panel">
    <h2>Why it matters</h2>
    <p>${esc(r[7])}</p>
    <h3>Moments to know</h3>
    <ul class="rvlist">${r[8].map(m => `<li>${esc(m)}</li>`).join("")}</ul>
    <h3>When they meet</h3>
    <p>${esc(r[6])}</p>
  </section>`;
}

