/* ---- hot.js ---- */
/* ---------- Hot right now: a bandwagon finder (added v40) ----------
   Teams winning right now: recent winning runs (from GAMES) and the leader of every league that is playing. */
const hotMetric = (sp, t) => typeof sp.metric === "function" ? sp.metric(t) : (t.st.W || 0) / Math.max(1, (t.st.W || 0) + (t.st.L || 0));
function winRun(sp, t) {
  const list = typeof gamesOf === "function" ? gamesOf(sp.id) : null; if (!list) return 0;
  const done = list.filter(g => g.as != null && (g.a === t.a || g.h === t.a));
  let n = 0; for (let i = done.length - 1; i >= 0; i--) { const g = done[i], us = g.h === t.a ? g.hs : g.as, them = g.h === t.a ? g.as : g.hs; if (us > them) n++; else break; }
  return n;
}
function hotLeaders() {
  const order = ["nba", "nfl", "nhl", "mlb", "mls", "wnba", "nwsl", "pwhl"];
  return Object.keys(SPORTS).filter(id => statusOf(id) === "Playing now" && SPORTS[id].teams.length > 1)
    .sort((a, b) => (order.includes(a) ? order.indexOf(a) : 99) - (order.includes(b) ? order.indexOf(b) : 99) || SPORTS[a].name.localeCompare(SPORTS[b].name))
    .map(id => { const sp = SPORTS[id], t = sp.teams.slice().sort((x, y) => hotMetric(sp, y) - hotMetric(sp, x))[0]; return { sp, t }; });
}
function vHot() {
  const runs = ["nba", "nhl"].filter(id => SPORTS[id]).flatMap(id => SPORTS[id].teams.map(t => ({ sp: SPORTS[id], t, n: winRun(SPORTS[id], t) }))).filter(x => x.n >= 3).sort((a, b) => b.n - a.n || a.t.n.localeCompare(b.t.n));
  const row = (sp, t, extra, rec) => `<tr><td class="hotteam"><a href="${teamHref(t)}">${badge(t, "")}<span><b>${esc(t.n)}</b><small class="hotlg">${esc(sp.name)}</small></span></a></td><td class="hotcol">${esc(sp.name)}</td><td class="num">${rec ? recCell(sp, t) : esc(extra)}</td></tr>`;
  const leaders = hotLeaders();
  return `
  <section class="hero">
    <p class="eyebrow">Hot right now</p>
    <h1>Jump on a winning team.</h1>
    <p class="lede">Want a team that is fun to follow straight away? These teams are winning right now. Supporting a team because it is doing well is called jumping on the bandwagon, and every fan base has a few who did.</p>
  </section>
  ${runs.length ? `<section class="panel">
    <h2>On a winning run</h2>
    <p class="hint">NBA and NHL teams that have won at least their last three games. Games are counted from November 13 to ${esc(GAMES.asof)}, so a longer run may have started earlier.</p>
    <div class="twrap"><table class="hottable"><thead><tr><th>Team</th><th class="hotcol">League</th><th class="num">Wins in a row</th></tr></thead><tbody>${runs.map(x => row(x.sp, x.t, String(x.n))).join("")}</tbody></table></div>
  </section>` : ""}
  <section class="panel">
    <h2>Top of the table</h2>
    <p class="hint">The team with the best record in every league that is playing now. Open a team to see its story and stars before you commit.</p>
    <div class="twrap"><table class="hottable"><thead><tr><th>Team</th><th class="hotcol">League</th><th class="num">Record</th></tr></thead><tbody>${leaders.map(x => row(x.sp, x.t, "", true)).join("")}</tbody></table></div>
    <p class="muted">Records list wins first, then losses, then draws or overtime losses where the sport has them. Select a record to have it read out in words.</p>
  </section>`;
}

;
