  if (!box) { box = document.createElement("div"); box.id = "tipbox"; box.setAttribute("role", "status"); box.setAttribute("aria-live", "polite"); document.body.appendChild(box); }
  box.textContent = el.dataset.tip; box.classList.add("on");
