/* ---------- Your team: saved in this browser, shown on the home page ---------- */
/* One saved team per league, kept in the order they were saved. */
function myTeams() {
  return Object.entries(state.my || {}).map(([id, a]) => { const sp = SPORTS[id], t = sp && sp.teams.find(x => x.a === a); return t ? { sp, t } : null; }).filter(Boolean);
}
