  const lgOpts = byName.map(([n, list]) => `<optgroup label="${esc(n)}">${list.map(x => `<option value="${x}"${x === sp.id ? " selected" : ""}>${esc(SPORTS[x].name)}</option>`).join("")}</optgroup>`).join("");
