  const chips = RQ_SPORTS.map(s => `<a class="chip" id="rq-${s[0]}" href="#rules-${s[0]}"${s[0] === sp ? ' aria-current="page"' : ""}>${sportIcon(s[2])} ${esc(s[1])}</a>`).join("");
