        <div class="answers two">${q.opts.map((o, i) => `<button type="button" class="ans${picked ? (o === q.ans ? " right" : o === picked ? " wrong" : " dim") : ""}" id="rqa-${i}" data-act="rqa" data-id="${i}" ${picked ? "disabled" : ""}>${esc(o)}</button>`).join("")}</div>
