document.addEventListener("click", e => {
  const b = e.target.closest("[data-act]");
  if (!b) return;
  const id = b.dataset.id, sp = sportNow();
  switch (b.dataset.act) {
    case "scroll": { const el = document.getElementById(id); if (el) el.scrollIntoView({ behavior: window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth", block: "start" }); break; }
    case "mode": if (sp) { if (id) state.mode[sp.id] = id; else state.mode[sp.id] = "";
      /* "I am brand new" starts the questions, unless they were already answered for another sport: then the matches show straight away. */
      if (id === "new" && state.done) state.reused = sp.id;
      if (id === "new" && !state.done) { state.ans = Array(NQ).fill(null); state.pick = ""; state.step = 0; state.done = false; } state.showAll = false; save(); render(true, id === "new" && !state.done ? "qtext" : ""); window.scrollTo(0, 0); } break;
    case "ans": state.ans[state.step] = Number(id); nextStep(); break;
    case "skip": state.ans[state.step] = null; nextStep(); break;
    case "back": state.step = Math.min(NQ - 1, Math.max(0, state.step - 1)); render(true, "qtext"); break;
    case "pick": state.pick = id; finishQuiz(); break;
    case "retake": state.reused = ""; state.ans = Array(NQ).fill(null); state.pick = ""; state.step = 0; state.done = false; save(); render(true, "qtext"); break;
    case "x": if (sp) { const cur = state.x[sp.id] || []; state.x[sp.id] = cur.includes(id) ? cur.filter(k => k !== id) : cur.concat(id); save(); render(true); } break;
    case "showall": state.showAll = !state.showAll; render(true); break;
    case "lf": state.lf[id] = !state.lf[id]; render(true); break;
    case "col": { const i = state.col.indexOf(id); if (i < 0) state.col.push(id); else state.col.splice(i, 1); save(); render(true, "col-" + id); break; }
    case "cmpswap": { const r = parse((location.hash || "").replace(/^#/, "")), c = cmpPick(r.lg, r.a, r.b); history.replaceState(null, "", cmpHref(c.sp, c.B, c.A)); render(true, "cmp-swap"); break; }
    case "rqa": RQ.picks[RQ.i] = RQ.qs[RQ.i].opts[+id]; render(true, "rq-next"); break;
    case "rqn": RQ.i++; render(true, RQ.i >= RQ.qs.length ? "rq-again" : "rqa-0"); break;
    case "rqgo": rqStart(RQ.sp); render(true, "rqa-0"); break;
    case "mymove": { const [k, d] = id.split(":"); moveMy(k, +d); render(true, null); break; }
    case "myteam": { const [lg, a] = id.split(":"); state.my = state.my || {}; if (state.my[lg] === a) delete state.my[lg]; else { delete state.my[lg]; state.my[lg] = a; } save(); render(true, document.getElementById("btn-my") ? "btn-my" : ""); break; }
    case "share": shareTeam(id); break;
    case "shareres": shareResult(id); break;
    case "landed": state.landed = true; save(); setTimeout(() => { if ((location.hash || "#home") === "#home") render(false); window.scrollTo(0, 0); }, 0); break;
    case "welcomed": state.welcomed = true; save(); { const el = document.getElementById("welcome"); if (el) el.remove(); } break;
    case "bs": state.bs = id; state.gt = id; state.gq = ""; render(true, "bs-" + id); break;
    case "gt": state.gt = id; state.gq = ""; render(true, "gt-" + id); if (b.classList.contains("linkbtn")) { const el = document.getElementById("dictionary"); if (el) el.scrollIntoView({ behavior: smoothScroll(), block: "start" }); } break;
    case "sx": state.sx = +id; render(true, "sx-" + id); break;
    case "ax": state.ax = id; render(true, "ax-" + id); break;
    case "mreg": state.mreg = +id; render(true, "mreg-" + id); break;
    case "mgrp": state.mg = state.mg || {}; state.mg[id] = !state.mg[id]; render(true, "mgrp-" + fold(id).replace(/[^a-z0-9]/g, "")); break;
    case "mz": mapZoom(id); break;
    case "vdot": mapInfo(+id); break;
    case "mmdot": miniInfo(+id); break;
    case "mgsp": { const g = MAP_GROUPS.find(x => x[0] === id); if (g) { state.mg = state.mg || {}; const anyOn = g[2].some(l => !state.mg[l]); g[2].forEach(l => { state.mg[l] = anyOn; }); } render(true, "mgsp-" + id); break; }
    case "mall": { const r = mregion(); state.mg = state.mg || {}; MAP_GROUPS.filter(g => g[3] === r).forEach(g => g[2].forEach(l => { state.mg[l] = id === "off"; })); render(true, "mall-" + id); break; }
    case "lg": state.lg = id; render(true, "lg-" + id); break;
    case "psp": state.psp = id; state.pt = ""; state.pc = ""; if (/^#players-/.test(location.hash)) history.replaceState(null, "", "#players-" + id); render(true, "psp-" + id); break;
    case "tqs": TQ.sp = id; TQ.team = ""; TQ.qs = null; render(true, "tqs-" + id); break;
    case "tqgo": startQuiz(); render(true, "tqa-0"); { const c = document.getElementById("tq-card"); if (c && c.getBoundingClientRect().top < 0) c.scrollIntoView({ behavior: smoothScroll(), block: "start" }); } break;
    case "tqa": TQ.picks[TQ.i] = TQ.qs[TQ.i].opts[+id]; render(true, "tq-next"); break;
    case "tqn": TQ.i++; render(true, TQ.i >= TQ.qs.length ? "tq-again" : "tqa-0"); break;
  }
});
document.addEventListener("input", e => {
  const el = e.target;
  if (el.id === "pq") { state.pq = el.value; setOut("p-out", playersOut()); }
  else if (el.id === "near") { state.near = el.value; setOut("near-out", nearOut2()); mapFocus(state.near); }
  else if (el.id === "gq") { state.gq = el.value; setOut("g-out", glossHTML()); }
});
document.addEventListener("change", e => {
  if (e.target.id === "pc") {
    state.pc = e.target.value; state.pq = "";
    const q = document.getElementById("pq"); if (q) q.value = "";
    setOut("p-out", playersOut());
  } else if (e.target.id === "loc") { state.loc = e.target.value; save(); render(true, "loc"); }
  else if (e.target.id === "tqt") { TQ.team = e.target.value; TQ.qs = null; render(true, "tqt"); }
  else if (e.target.id === "tqs-more" && e.target.value && SPORTS[e.target.value]) { TQ.sp = e.target.value; TQ.team = ""; TQ.qs = null; render(true, "tqs-more"); }
  else if (e.target.id === "mp") { state.mp = e.target.value; render(true, "mp"); }
});
window.addEventListener("hashchange", () => render(false));
